INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('KISW.G3.SARUFI.T10_VINYUME_VYA_VITENDO.a', 'KISW.G3.SARUFI.T10_VINYUME_VYA_VITENDO', 'a', 'kutambua vinyume vya vitendo katika matini', 'kicd_verified') ON CONFLICT (code) DO NOTHING;
INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('KISW.G3.SARUFI.T10_VINYUME_VYA_VITENDO.b', 'KISW.G3.SARUFI.T10_VINYUME_VYA_VITENDO', 'b', 'kutumia vinyume vya vitendo ipasavyo katika matini', 'kicd_verified') ON CONFLICT (code) DO NOTHING;
