INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'KISW.G3.KUSIKI.T1_MAAMKUZI_NA_MAAGANO', 'kiswahili', 3, 'Tumia maamkuzi na maagano yafaayo na majibu yake', ARRAY['KISW.G3.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.a', 'KISW.G3.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.b']::text[], 'Chooses the greeting or farewell that fits who is met (a friend, an elder, a group), the time of day and whether arriving or leaving, and gives the right reply (Hujambo? Sijambo; Shikamoo, Marahaba; Hamjambo? Hatujambo), in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua salamu ifaayo","chagua jibu la salamu","igiza salamu (mwalimu anasikiliza)"]'::jsonb, '["recall","application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'KISW.G3.KUSOMA.T1_KUSOMA_KWA_UFAHAMU', 'kiswahili', 3, 'Soma kifungu chepesi: msamiati, ujumbe, kutabiri na mafunzo', ARRAY['KISW.G3.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.a', 'KISW.G3.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.b', 'KISW.G3.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.c', 'KISW.G3.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.d']::text[], 'Reads a short passage on uzalendo, gives the meaning of a theme word from the sentence around it, says the message, predicts what happens next from the clues and says the lesson, answering from the passage and not from his own life, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua maana ya neno","chagua ujumbe","tabiri kitakachotokea","chagua funzo"]'::jsonb, '["comprehension","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUANDI.T1_HATI_NADHIFU_KIFUNGU.HATI_NADHIFU', 'KISW.G3.KUANDI.T1_HATI_NADHIFU_KIFUNGU', 'kiswahili', 3, 'Andika kifungu kwa hati nadhifu', ARRAY['KISW.G3.KUANDI.T1_HATI_NADHIFU_KIFUNGU.a', 'KISW.G3.KUANDI.T1_HATI_NADHIFU_KIFUNGU.b']::text[], 'Writes a passage of about 25-30 words in neat handwriting: letters well formed and on the line, space between words, through the steps to a clean copy, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua maandishi nadhifu","tambua kosa","andika kifungu (mwalimu anasahihisha)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.SARUFI.T1_MATUMIZI_YA_YEYE_NA_.NAFSI', 'KISW.G3.SARUFI.T1_MATUMIZI_YA_YEYE_NA_', 'kiswahili', 3, 'Tumia yeye na wao ipasavyo katika sentensi', ARRAY['KISW.G3.SARUFI.T1_MATUMIZI_YA_YEYE_NA_.a', 'KISW.G3.SARUFI.T1_MATUMIZI_YA_YEYE_NA_.b']::text[], 'Uses yeye for one person (a boy or a girl) and wao for many, with the matching subject marker on the verb (yeye a-, wao wa-), and switches to yeye when answering about someone else, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUSIKI.T2_MATAMSHI_BORA_VOKALI.VOKALI_KONSONANTI', 'KISW.G3.KUSIKI.T2_MATAMSHI_BORA_VOKALI', 'kiswahili', 3, 'Tambua na utamke vokali na konsonanti za Kiswahili', ARRAY['KISW.G3.KUSIKI.T2_MATAMSHI_BORA_VOKALI.a', 'KISW.G3.KUSIKI.T2_MATAMSHI_BORA_VOKALI.b', 'KISW.G3.KUSIKI.T2_MATAMSHI_BORA_VOKALI.c', 'KISW.G3.KUSIKI.T2_MATAMSHI_BORA_VOKALI.d']::text[], 'Names the five Kiswahili vowels (a, e, i, o, u), tells a vowel from a consonant, says each with its Kiswahili sound (not the English letter name), and treats ch, sh, dh, th, gh, ny, ng'' as one consonant each, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua irabu","tambua konsonanti","chagua matamshi sahihi","tamka sauti (mwalimu anasikiliza)"]'::jsonb, '["recall","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'KISW.G3.KUSOMA.T2_KUSOMA_KWA_UFASAHA', 'kiswahili', 3, 'Soma kifungu chepesi chenye sauti /bw/, /fy/, /kw/ kwa matamshi bora, sauti inayosikika, kasi ifaayo na ishara', ARRAY['KISW.G3.KUSOMA.T2_KUSOMA_KWA_UFASAHA.a', 'KISW.G3.KUSOMA.T2_KUSOMA_KWA_UFASAHA.b', 'KISW.G3.KUSOMA.T2_KUSOMA_KWA_UFASAHA.c', 'KISW.G3.KUSOMA.T2_KUSOMA_KWA_UFASAHA.d', 'KISW.G3.KUSOMA.T2_KUSOMA_KWA_UFASAHA.e']::text[], 'Finds the target sounds /bw/, /fy/, /kw/ in a short story, reads it aloud with every sound clear, loud enough for the class, at about 47 words a minute, pausing at the koma and kikomo and raising the voice for a question; in the app picks the better reading of a line, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["tambua sauti lengwa","chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUANDI.T2_HATI_NADHIFU.HATI_NADHIFU', 'KISW.G3.KUANDI.T2_HATI_NADHIFU', 'kiswahili', 3, 'Andika kwa hati nadhifu ukitumia herufi kubwa ifaavyo', ARRAY['KISW.G3.KUANDI.T2_HATI_NADHIFU.a', 'KISW.G3.KUANDI.T2_HATI_NADHIFU.b']::text[], 'Writes a passage of about 25-30 words in neat handwriting: letters well formed and on the line, capitals only at the start of a sentence or name, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua maandishi nadhifu","tambua kosa","andika kifungu (mwalimu anasahihisha)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.SARUFI.T2_UMOJA_NA_WINGI_WA_SE.UMOJA_WINGI', 'KISW.G3.SARUFI.T2_UMOJA_NA_WINGI_WA_SE', 'kiswahili', 3, 'Badilisha sentensi kutoka umoja hadi wingi na kinyume chake', ARRAY['KISW.G3.SARUFI.T2_UMOJA_NA_WINGI_WA_SE.a', 'KISW.G3.SARUFI.T2_UMOJA_NA_WINGI_WA_SE.b']::text[], 'Turns a short sentence from singular to plural and back, changing the noun by its ngeli (kiatu - viatu, mti - miti, jembe - majembe) and every word that agrees with it, including the verb, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUSIKI.T3_MANENO_YA_HESHIMA_NA.HESHIMA', 'KISW.G3.KUSIKI.T3_MANENO_YA_HESHIMA_NA', 'kiswahili', 3, 'Tumia maneno ya heshima na adabu: tafadhali, asante, samahani, pole, karibu', ARRAY['KISW.G3.KUSIKI.T3_MANENO_YA_HESHIMA_NA.a', 'KISW.G3.KUSIKI.T3_MANENO_YA_HESHIMA_NA.b']::text[], 'Picks and uses the polite word that fits the situation (tafadhali or naomba to ask, asante to thank, karibu to answer asante, samahani to apologise, pole to sympathise) and addresses an adult with a title, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno la adabu","kamilisha mazungumzo","igiza hali (mwalimu anasikiliza)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'KISW.G3.KUSOMA.T3_KUSOMA_KWA_UFAHAMU', 'kiswahili', 3, 'Soma kifungu chepesi: msamiati, ujumbe, kutabiri na mafunzo', ARRAY['KISW.G3.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.a', 'KISW.G3.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.b', 'KISW.G3.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.c', 'KISW.G3.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.d']::text[], 'Reads a short passage on miezi ya mwaka, gives the meaning of a theme word from the sentence around it, says the message, predicts what happens next from the clues and says the lesson, answering from the passage and not from his own life, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua maana ya neno","chagua ujumbe","tabiri kitakachotokea","chagua funzo"]'::jsonb, '["comprehension","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUANDI.T3_HATI_NADHIFU.HATI_NADHIFU', 'KISW.G3.KUANDI.T3_HATI_NADHIFU', 'kiswahili', 3, 'Andika kwa hati nadhifu ukitumia herufi ndogo ifaavyo', ARRAY['KISW.G3.KUANDI.T3_HATI_NADHIFU.a', 'KISW.G3.KUANDI.T3_HATI_NADHIFU.b']::text[], 'Writes a passage of about 55-60 words in neat handwriting: letters well formed and on the line, small letters of the right height, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua maandishi nadhifu","tambua kosa","andika kifungu (mwalimu anasahihisha)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.SARUFI.T3_MATUMIZI_YA_MANENO_Y.VIONYESHI', 'KISW.G3.SARUFI.T3_MATUMIZI_YA_MANENO_Y', 'kiswahili', 3, 'Tumia yule na wale ipasavyo katika sentensi', ARRAY['KISW.G3.SARUFI.T3_MATUMIZI_YA_MANENO_Y.a', 'KISW.G3.SARUFI.T3_MATUMIZI_YA_MANENO_Y.b']::text[], 'Uses yule for one person or animal far away and wale for many, tells them from huyu/hawa (near), and uses kile/vile, not yule, for things of the ki-vi class, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUSIKI.T4_MATAMSHI_BORA.MATAMSHI', 'KISW.G3.KUSIKI.T4_MATAMSHI_BORA', 'kiswahili', 3, 'Tambua na utamke silabi za sauti /py/, /vy/, /sh/ katika maneno na sentensi', ARRAY['KISW.G3.KUSIKI.T4_MATAMSHI_BORA.a', 'KISW.G3.KUSIKI.T4_MATAMSHI_BORA.b', 'KISW.G3.KUSIKI.T4_MATAMSHI_BORA.c']::text[], 'Hears and says the target sounds /py/, /vy/, /sh/ in syllables and words (kipya, vyakula, shamba), splits a word into its syllables, and picks or uses a word that carries the sound, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno lenye sauti","gawa neno kwa silabi","chagua matamshi sahihi","tamka neno (mwalimu anasikiliza)"]'::jsonb, '["recall","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI', 'KISW.G3.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S', 'kiswahili', 3, 'Soma kifungu chepesi chenye sauti /py/, /vy/, /sh/ kwa matamshi bora, sauti inayosikika, kasi ifaayo na ishara', ARRAY['KISW.G3.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.a', 'KISW.G3.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.b', 'KISW.G3.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.c', 'KISW.G3.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.d', 'KISW.G3.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.e']::text[], 'Finds the target sounds /py/, /vy/, /sh/ in a short story, reads it aloud with every sound clear, loud enough for the class, at about 49 words a minute, pausing at the koma and kikomo and raising the voice for a question; in the app picks the better reading of a line, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["tambua sauti lengwa","chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUANDI.T4_NAFASI_YA_PAMBIZO_KA.PAMBIZO_AYA', 'KISW.G3.KUANDI.T4_NAFASI_YA_PAMBIZO_KA', 'kiswahili', 3, 'Andika kifungu ukizingatia pambizo, aya na nafasi kati ya maneno', ARRAY['KISW.G3.KUANDI.T4_NAFASI_YA_PAMBIZO_KA.a', 'KISW.G3.KUANDI.T4_NAFASI_YA_PAMBIZO_KA.b']::text[], 'Writes a passage of up to 60 words that keeps out of the margin, leaves space between words, starts a new aya for a new idea and breaks a long word at the end of a line only between syllables, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["tambua pambizo na aya","chagua mpangilio sahihi","andika kifungu (mwalimu anasahihisha)"]'::jsonb, '["application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.SARUFI.T4_UMOJA_NA_WINGI_WA_SE.UMOJA_WINGI', 'KISW.G3.SARUFI.T4_UMOJA_NA_WINGI_WA_SE', 'kiswahili', 3, 'Andika sentensi za kazi mbalimbali katika umoja na wingi', ARRAY['KISW.G3.SARUFI.T4_UMOJA_NA_WINGI_WA_SE.a', 'KISW.G3.SARUFI.T4_UMOJA_NA_WINGI_WA_SE.b']::text[], 'Writes sentences about workers in singular and plural: people nouns take wa- (mwalimu - walimu, mpishi - wapishi), li-ma nouns take ma- or change (daktari - madaktari, jino - meno), and the verb agrees, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA', 'KISW.G3.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ', 'kiswahili', 3, 'Sikiliza kifungu, eleza ujumbe na msamiati wake, na usimulie upya', ARRAY['KISW.G3.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.a', 'KISW.G3.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.b', 'KISW.G3.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.c', 'KISW.G3.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.d']::text[], 'After hearing a short passage (Wanjiru alivuka barabara bila kuangalia na nusura agongwe na gari), says its message, gives the meaning of a new word from it, uses the word in a sentence of his own and retells the events in order, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua ujumbe","chagua maana ya neno","panga matukio","simulia upya (mwalimu anasikiliza)"]'::jsonb, '["comprehension","sequencing"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'KISW.G3.KUSOMA.T5_KUSOMA_KWA_UFAHAMU', 'kiswahili', 3, 'Soma kifungu chepesi: msamiati, ujumbe, kutabiri na mafunzo', ARRAY['KISW.G3.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.a', 'KISW.G3.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.b', 'KISW.G3.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.c', 'KISW.G3.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.d']::text[], 'Reads a short passage on usalama, gives the meaning of a theme word from the sentence around it, says the message, predicts what happens next from the clues in the picture and says the lesson, answering from the passage and not from his own life, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua maana ya neno","chagua ujumbe","tabiri kitakachotokea","chagua funzo"]'::jsonb, '["comprehension","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUANDI.T5_MATUMIZI_YA_KIULIZI.ALAMA', 'KISW.G3.KUANDI.T5_MATUMIZI_YA_KIULIZI', 'kiswahili', 3, 'Tumia alama ya kiulizi ipasavyo katika maandishi', ARRAY['KISW.G3.KUANDI.T5_MATUMIZI_YA_KIULIZI.a', 'KISW.G3.KUANDI.T5_MATUMIZI_YA_KIULIZI.b', 'KISW.G3.KUANDI.T5_MATUMIZI_YA_KIULIZI.c']::text[], 'Tells a question from a statement, ends each with its mark (? or .), starts the next sentence with a capital, and writes a passage of about 55-60 words with the marks in place, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["weka alama sahihi","chagua sentensi iliyoakifishwa vizuri","andika kifungu (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.SARUFI.T5_MATUMIZI_YA_AKE_NA_A.VIMILIKISHI', 'KISW.G3.SARUFI.T5_MATUMIZI_YA_AKE_NA_A', 'kiswahili', 3, 'Tumia -ake na -ao ipasavyo katika sentensi', ARRAY['KISW.G3.SARUFI.T5_MATUMIZI_YA_AKE_NA_A.a', 'KISW.G3.SARUFI.T5_MATUMIZI_YA_AKE_NA_A.b']::text[], 'Uses -ake for one owner and -ao for many owners, with the noun-class prefix of the thing owned (kiti chake, viti vyao, kofia yake), placed after the noun, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI', 'KISW.G3.KUSIKI.T6_MATAMSHI_BORA', 'kiswahili', 3, 'Tambua na utamke silabi za sauti /dh/, /th/, /ch/ katika maneno na sentensi', ARRAY['KISW.G3.KUSIKI.T6_MATAMSHI_BORA.a', 'KISW.G3.KUSIKI.T6_MATAMSHI_BORA.b', 'KISW.G3.KUSIKI.T6_MATAMSHI_BORA.c']::text[], 'Hears and says the target sounds /dh/, /th/, /ch/ in syllables and words (dhahabu, thelathini, chupa), splits a word into its syllables, and picks or uses a word that carries the sound, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno lenye sauti","gawa neno kwa silabi","chagua matamshi sahihi","tamka neno (mwalimu anasikiliza)"]'::jsonb, '["recall","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUSOMA.T6_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'KISW.G3.KUSOMA.T6_KUSOMA_KWA_UFASAHA', 'kiswahili', 3, 'Soma kifungu chepesi chenye sauti /dh/, /th/, /ch/ kwa matamshi bora, sauti inayosikika, kasi ifaayo na ishara', ARRAY['KISW.G3.KUSOMA.T6_KUSOMA_KWA_UFASAHA.a', 'KISW.G3.KUSOMA.T6_KUSOMA_KWA_UFASAHA.b', 'KISW.G3.KUSOMA.T6_KUSOMA_KWA_UFASAHA.c', 'KISW.G3.KUSOMA.T6_KUSOMA_KWA_UFASAHA.d', 'KISW.G3.KUSOMA.T6_KUSOMA_KWA_UFASAHA.e']::text[], 'Finds the target sounds /dh/, /th/, /ch/ in a short story, reads it aloud with every sound clear, loud enough for the class, at about 51 words a minute, pausing at the koma and kikomo and raising the voice for a question; in the app picks the better reading of a line, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["tambua sauti lengwa","chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUANDI.T6_IMLA.IMLA', 'KISW.G3.KUANDI.T6_IMLA', 'kiswahili', 3, 'Andika maneno yanayotamkwa kwenye imla kwa tahajia sahihi', ARRAY['KISW.G3.KUANDI.T6_IMLA.a', 'KISW.G3.KUANDI.T6_IMLA.b']::text[], 'Writes the words the teacher reads (about 55-60 words) with the right letters: the Kiswahili sound and not the home sound, the nasal kept (nd, mb, ng), long vowels doubled and ng'' with its apostrophe, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua tahajia sahihi","sahihisha neno","imla (mwalimu anasoma)"]'::jsonb, '["recall","application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.SARUFI.T6_MATUMIZI_YA_EUPE_EUS.VIVUMISHI', 'KISW.G3.SARUFI.T6_MATUMIZI_YA_EUPE_EUS', 'kiswahili', 3, 'Tumia -eupe, -eusi na -ekundu ipasavyo katika sentensi', ARRAY['KISW.G3.SARUFI.T6_MATUMIZI_YA_EUPE_EUS.a', 'KISW.G3.SARUFI.T6_MATUMIZI_YA_EUPE_EUS.b']::text[], 'Uses the colour stems -eupe, -eusi and -ekundu after the noun with the right noun-class prefix and its sound change (kiti cheupe, nguo nyeupe, mfuko mweusi, mifuko myeusi), in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUSIKI.T7_MAAGIZO.MAAGIZO', 'KISW.G3.KUSIKI.T7_MAAGIZO', 'kiswahili', 3, 'Fuata na utoe maagizo mepesi kwa usahihi', ARRAY['KISW.G3.KUSIKI.T7_MAAGIZO.a', 'KISW.G3.KUSIKI.T7_MAAGIZO.b']::text[], 'Follows a one- or two-step instruction in the right order, reads the direction and action words in it (simama, keti, kulia, kushoto, juu, chini), and gives a clear, polite instruction that names what to do and to what, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua kitendo sahihi","panga hatua","toa agizo (mwalimu anasikiliza)"]'::jsonb, '["comprehension","application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'KISW.G3.KUSOMA.T7_KUSOMA_KWA_UFAHAMU', 'kiswahili', 3, 'Soma kifungu chepesi: msamiati, ujumbe, kutabiri na mafunzo', ARRAY['KISW.G3.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.a', 'KISW.G3.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.b', 'KISW.G3.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.c', 'KISW.G3.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.d']::text[], 'Reads a short passage on dukani, gives the meaning of a theme word from the sentence around it, says the message, predicts what happens next from the clues and says the lesson, answering from the passage and not from his own life, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua maana ya neno","chagua ujumbe","tabiri kitakachotokea","chagua funzo"]'::jsonb, '["comprehension","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUANDI.T7_UANDISHI_WA_INSHA.INSHA', 'KISW.G3.KUANDI.T7_UANDISHI_WA_INSHA', 'kiswahili', 3, 'Andika kisa kifupi chenye mwanzo, kati na mwisho', ARRAY['KISW.G3.KUANDI.T7_UANDISHI_WA_INSHA.a', 'KISW.G3.KUANDI.T7_UANDISHI_WA_INSHA.b']::text[], 'Writes a short story of about 85-90 words on dukani: a title that fits, sentences in order, one tense, Kiswahili words only, capitals and kikomo in place, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua kichwa kifaacho","panga sentensi","tambua kosa","andika (mwalimu anasahihisha)"]'::jsonb, '["application","sequencing"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.SARUFI.T7_UKANUSHAJI_WA_NAFSI_.UKANUSHAJI', 'KISW.G3.SARUFI.T7_UKANUSHAJI_WA_NAFSI_', 'kiswahili', 3, 'Kanusha sentensi za nafsi ya tatu umoja na wingi', ARRAY['KISW.G3.SARUFI.T7_UKANUSHAJI_WA_NAFSI_.a', 'KISW.G3.SARUFI.T7_UKANUSHAJI_WA_NAFSI_.b']::text[], 'Makes the negative of a present-tense sentence in the third person: yeye anauza - yeye hauzi, wao wanauza - wao hawauzi (ha-/hawa-, no -na-, final -a to -i), in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI', 'KISW.G3.KUSIKI.T8_MATAMSHI_BORA', 'kiswahili', 3, 'Tambua na utamke silabi za sauti /mbw/, /nd/, /ny/ katika maneno na sentensi', ARRAY['KISW.G3.KUSIKI.T8_MATAMSHI_BORA.a', 'KISW.G3.KUSIKI.T8_MATAMSHI_BORA.b', 'KISW.G3.KUSIKI.T8_MATAMSHI_BORA.c']::text[], 'Hears and says the target sounds /mbw/, /nd/, /ny/ in syllables and words (mbweha, ndege, nyumba), splits a word into its syllables, and picks or uses a word that carries the sound, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno lenye sauti","gawa neno kwa silabi","chagua matamshi sahihi","tamka neno (mwalimu anasikiliza)"]'::jsonb, '["recall","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'KISW.G3.KUSOMA.T8_KUSOMA_KWA_UFASAHA', 'kiswahili', 3, 'Soma kifungu chepesi chenye sauti /mbw/, /nd/, /ny/ kwa matamshi bora, sauti inayosikika, kasi ifaayo na ishara', ARRAY['KISW.G3.KUSOMA.T8_KUSOMA_KWA_UFASAHA.a', 'KISW.G3.KUSOMA.T8_KUSOMA_KWA_UFASAHA.b', 'KISW.G3.KUSOMA.T8_KUSOMA_KWA_UFASAHA.c', 'KISW.G3.KUSOMA.T8_KUSOMA_KWA_UFASAHA.d', 'KISW.G3.KUSOMA.T8_KUSOMA_KWA_UFASAHA.e']::text[], 'Finds the target sounds /mbw/, /nd/, /ny/ in a short story, reads it aloud with every sound clear, loud enough for the class, at about 53 words a minute, pausing at the koma and kikomo and raising the voice for a question; in the app picks the better reading of a line, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["tambua sauti lengwa","chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUANDI.T8_TAHAJIA.TAHAJIA', 'KISW.G3.KUANDI.T8_TAHAJIA', 'kiswahili', 3, 'Andika insha fupi kwa tahajia sahihi za maneno', ARRAY['KISW.G3.KUANDI.T8_TAHAJIA.a', 'KISW.G3.KUANDI.T8_TAHAJIA.b']::text[], 'Writes the words of his own writing (about 85-90 words) with the right letters: the Kiswahili sound and not the home sound, the nasal kept (nd, mb, ng), long vowels doubled and ng'' with its apostrophe, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua tahajia sahihi","sahihisha neno","andika (mwalimu anasahihisha)"]'::jsonb, '["recall","application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.SARUFI.T8_MATUMIZI_YA_MANENO_H.VIONYESHI', 'KISW.G3.SARUFI.T8_MATUMIZI_YA_MANENO_H', 'kiswahili', 3, 'Tumia hili na haya ipasavyo katika kifungu', ARRAY['KISW.G3.SARUFI.T8_MATUMIZI_YA_MANENO_H.a', 'KISW.G3.SARUFI.T8_MATUMIZI_YA_MANENO_H.b']::text[], 'Uses hili with a near li-ma noun in the singular and haya in the plural (yai hili - mayai haya, jicho hili - macho haya), not huyu or hii, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUSIKI.T9_MAZUNGUMZO.MAZUNGUMZO', 'KISW.G3.KUSIKI.T9_MAZUNGUMZO', 'kiswahili', 3, 'Shiriki mazungumzo kuhusu bidhaa za sokoni kwa zamu, kwa matamshi bora na ishara zifaazo', ARRAY['KISW.G3.KUSIKI.T9_MAZUNGUMZO.a', 'KISW.G3.KUSIKI.T9_MAZUNGUMZO.b', 'KISW.G3.KUSIKI.T9_MAZUNGUMZO.c', 'KISW.G3.KUSIKI.T9_MAZUNGUMZO.d']::text[], 'Takes part in a short conversation about bidhaa za sokoni: keeps to the topic, waits for his turn, speaks Kiswahili without English or Sheng words, says sounds clearly and uses gestures that match the words, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua jibu linalofaa mada","tambua kosa la mazungumzo","zungumza (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'KISW.G3.KUSOMA.T9_KUSOMA_KWA_UFAHAMU', 'kiswahili', 3, 'Soma kifungu chepesi: msamiati, ujumbe, kutabiri na mafunzo', ARRAY['KISW.G3.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.a', 'KISW.G3.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.b', 'KISW.G3.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.c', 'KISW.G3.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.d']::text[], 'Reads a short passage on sokoni, gives the meaning of a theme word from the sentence around it, says the message, predicts what happens next from the clues in the picture and says the lesson, answering from the passage and not from his own life, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua maana ya neno","chagua ujumbe","tabiri kitakachotokea","chagua funzo"]'::jsonb, '["comprehension","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUANDI.T9_INSHA_YA_MASIMULIZI.INSHA', 'KISW.G3.KUANDI.T9_INSHA_YA_MASIMULIZI', 'kiswahili', 3, 'Andika insha fupi ya masimulizi', ARRAY['KISW.G3.KUANDI.T9_INSHA_YA_MASIMULIZI.a', 'KISW.G3.KUANDI.T9_INSHA_YA_MASIMULIZI.b']::text[], 'Writes a short insha ya masimulizi of about 85-90 words on sokoni: a title that fits, sentences in order, one tense, Kiswahili words only, capitals and kikomo in place, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua kichwa kifaacho","panga sentensi","tambua kosa","andika (mwalimu anasahihisha)"]'::jsonb, '["application","sequencing"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.SARUFI.T9_YA_JUU_YA.VIHUSISHI', 'KISW.G3.SARUFI.T9_YA_JUU_YA', 'kiswahili', 3, 'Tumia juu ya, ndani ya na mbele ya katika sentensi', ARRAY['KISW.G3.SARUFI.T9_YA_JUU_YA.a', 'KISW.G3.SARUFI.T9_YA_JUU_YA.b']::text[], 'Says where something is with juu ya, ndani ya and mbele ya (and their opposites chini ya, nje ya, nyuma ya), keeping ya and not adding -ni to the noun, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI', 'KISW.G3.KUSIKI.T10_MATAMSHI_BORA', 'kiswahili', 3, 'Tambua na utamke silabi za sauti /mb/, /nz/, /tw/ katika maneno na sentensi', ARRAY['KISW.G3.KUSIKI.T10_MATAMSHI_BORA.a', 'KISW.G3.KUSIKI.T10_MATAMSHI_BORA.b', 'KISW.G3.KUSIKI.T10_MATAMSHI_BORA.c']::text[], 'Hears and says the target sounds /mb/, /nz/, /tw/ in syllables and words (mbali, nzuri, twiga), splits a word into its syllables, and picks or uses a word that carries the sound, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno lenye sauti","gawa neno kwa silabi","chagua matamshi sahihi","tamka neno (mwalimu anasikiliza)"]'::jsonb, '["recall","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'KISW.G3.KUSOMA.T10_KUSOMA_KWA_UFASAHA', 'kiswahili', 3, 'Soma kifungu chepesi chenye sauti /mb/, /nz/, /tw/ kwa matamshi bora, sauti inayosikika, kasi ifaayo na ishara', ARRAY['KISW.G3.KUSOMA.T10_KUSOMA_KWA_UFASAHA.a', 'KISW.G3.KUSOMA.T10_KUSOMA_KWA_UFASAHA.b', 'KISW.G3.KUSOMA.T10_KUSOMA_KWA_UFASAHA.c', 'KISW.G3.KUSOMA.T10_KUSOMA_KWA_UFASAHA.d', 'KISW.G3.KUSOMA.T10_KUSOMA_KWA_UFASAHA.e']::text[], 'Finds the target sounds /mb/, /nz/, /tw/ in a short story, reads it aloud with every sound clear, loud enough for the class, at about 55 words a minute, pausing at the koma and kikomo and raising the voice for a question; in the app picks the better reading of a line, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["tambua sauti lengwa","chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.KUANDI.T10_INSHA_YA_MAELEZO.INSHA', 'KISW.G3.KUANDI.T10_INSHA_YA_MAELEZO', 'kiswahili', 3, 'Andika insha fupi ya maelezo', ARRAY['KISW.G3.KUANDI.T10_INSHA_YA_MAELEZO.a', 'KISW.G3.KUANDI.T10_INSHA_YA_MAELEZO.b']::text[], 'Writes a short insha ya maelezo of about 85-90 words on teknolojia: a title that fits, sentences in order, one tense, Kiswahili words only, capitals and kikomo in place, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua kichwa kifaacho","panga sentensi","tambua kosa","andika (mwalimu anasahihisha)"]'::jsonb, '["application","sequencing"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G3.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME', 'KISW.G3.SARUFI.T10_VINYUME_VYA_VITENDO', 'kiswahili', 3, 'Tambua na utumie vinyume vya vitendo', ARRAY['KISW.G3.SARUFI.T10_VINYUME_VYA_VITENDO.a', 'KISW.G3.SARUFI.T10_VINYUME_VYA_VITENDO.b']::text[], 'Gives and uses the opposite action of a verb (fungua - funga, washa - zima, keti - simama, ingia - toka), not its negative, a word of the same meaning, or a place word, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
