INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('KISW.G3.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME', 'KISW.G3.SARUFI.T7_UKANUSHAJI_WA_NAFSI_.UKANUSHAJI', 'skill', 'helpful', 'Knowing the negative lets the child tell it from the opposite.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M3_SAL_REPLY_T1', 'KISW.G3.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Answers a greeting with the same greeting (Hujambo? Hujambo!) instead of its reply.', '{"question":"Rafiki anakusalimu: \"Hujambo?\" Unajibu nini?","wrong_answer":"Hujambo","correct_answer":"Sijambo"}'::jsonb, 'The child hears the greeting as a sound to echo, as with "Hello" in English; the question-and-answer pair has not been learnt.', 'The question "Rafiki anakusalimu: "Hujambo?" Unajibu nini?" with "Hujambo" among the options.', 'Act it as a ball game: the greeting is thrown, the reply is caught; the two words are on two different cards.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M3_SAL_ELDER_T1', 'KISW.G3.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Greets an elder with a peer or Sheng greeting (Mambo! Sasa!) instead of Shikamoo.', '{"question":"Unamwona babu njiani. Unamsalimu vipi?","wrong_answer":"Mambo babu!","correct_answer":"Shikamoo babu!"}'::jsonb, 'Mambo and Sasa are what the child hears most among children and on the street; he has not been taught that an elder is greeted differently.', 'The question "Unamwona babu njiani. Unamsalimu vipi?" with "Mambo babu!" among the options.', 'Sort picture cards of people (babu, rafiki, mwalimu) into two piles: Shikamoo and Hujambo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M3_SAL_MARAHABA_T1', 'KISW.G3.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Gives the elder''s reply to the child''s greeting the wrong way round (the elder says Shikamoo, or the child says Marahaba).', '{"question":"Mtoto anamsalimu bibi: \"Shikamoo bibi!\" Bibi anajibu nini?","wrong_answer":"Shikamoo","correct_answer":"Marahaba"}'::jsonb, 'Both words are heard together and the child does not yet know which belongs to the young person and which to the elder.', 'The question "Mtoto anamsalimu bibi: "Shikamoo bibi!" Bibi anajibu nini?" with "Shikamoo" among the options.', 'Role-play with a hat for the elder: only the one with the hat may say Marahaba.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M3_SAL_TIME_T1', 'KISW.G3.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Uses the greeting of another time of day.', '{"question":"Unamkuta mwalimu shuleni saa nne asubuhi. Unamsalimu vipi?","wrong_answer":"Habari za jioni mwalimu!","correct_answer":"Habari za asubuhi mwalimu!"}'::jsonb, 'The child learnt one greeting as a set phrase and uses it at every hour.', 'The question "Unamkuta mwalimu shuleni saa nne asubuhi. Unamsalimu vipi?" with "Habari za jioni mwalimu!" among the options.', 'A clock or sun chart: asubuhi, mchana, jioni, usiku; the child moves the arrow and says the greeting for that time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M3_SAL_LEAVE_T1', 'KISW.G3.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Uses a greeting when leaving, or a farewell when arriving.', '{"question":"Rafiki anasafiri kwenda kijijini. Unamuaga vipi?","wrong_answer":"Karibu sana!","correct_answer":"Safiri salama!"}'::jsonb, 'Greeting and farewell words are learnt on one chart and the child mixes the two columns.', 'The question "Rafiki anasafiri kwenda kijijini. Unamuaga vipi?" with "Karibu sana!" among the options.', 'Act out a door: walk in and greet, walk out and say goodbye.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M3_SAL_GROUP_T1', 'KISW.G3.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Greets a group with the singular greeting (Hujambo?) or answers for a group with Sijambo.', '{"question":"Mwalimu anaingia darasani na kusema: \"Hamjambo wanafunzi?\" Darasa linajibu nini?","wrong_answer":"Sijambo","correct_answer":"Hatujambo"}'::jsonb, 'The child knows one pair only; the plural forms hamjambo/hatujambo follow the person marker (m-, tu-), which has not been noticed.', 'The question "Mwalimu anaingia darasani na kusema: "Hamjambo wanafunzi?" Darasa linajibu nini?" with "Sijambo" among the options.', 'Greet one child, then the whole row; show that the word changes with one or many.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU.M3_UFM_WORD_T1', 'KISW.G3.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Gives "bendera" the meaning of a word that looks or sounds like it.', '{"question":"Soma: \"Kila Jumatatu, wanafunzi wa Shule ya Amani hukusanyika uwanjani. Wanaimba wimbo wa taifa huku bendera ikipandishwa. Wote husimama wima kwa heshima.\" Neno \"bendera\" lina maana gani?","wrong_answer":"bandari","correct_answer":"kitambaa chenye rangi kinachowakilisha nchi"}'::jsonb, 'The child matches the word to a known one by its look instead of reading the sentence around it.', 'The question "Soma: "Kila Jumatatu, wanafunzi wa Shule ya Amani hukusanyika uwanjani. Wanaimba wimbo wa taifa huku bendera ikipandishwa. Wote husimama wima kwa heshima." Neno "bendera" lina maana gani?" with "bandari" among the options.', 'Cover the word; the child says what word would fit the sentence, then uncovers it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU.M3_UFM_MSG_T1', 'KISW.G3.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Gives one detail of the passage as its message.', '{"question":"Ujumbe wa kifungu ni upi?","wrong_answer":"Wanafunzi hukusanyika siku ya Jumatatu.","correct_answer":"Tunaheshimu wimbo wa taifa na bendera ya nchi yetu."}'::jsonb, 'The detail is what the child remembers best; he has not been asked what the writer wants us to know.', 'The question "Ujumbe wa kifungu ni upi?" with "Wanafunzi hukusanyika siku ya Jumatatu." among the options.', 'Ask two questions side by side: "Nini kilitokea?" and "Kifungu kinatuambia nini?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU.M3_UFM_GUESS_T1', 'KISW.G3.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Predicts something the passage gives no clue for.', '{"question":"Wimbo wa taifa ukiisha, wanafunzi watafanya nini?","wrong_answer":"Wataenda nyumbani kulala.","correct_answer":"Wataenda madarasani kuanza masomo."}'::jsonb, 'Prediction is taken as free imagination; the child has not been shown that clues in the text and picture point the way.', 'The question "Wimbo wa taifa ukiisha, wanafunzi watafanya nini?" with "Wataenda nyumbani kulala." among the options.', 'Underline the clue words; the guess must fit them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU.M3_UFM_LESSON_T1', 'KISW.G3.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Retells what happened when asked for the lesson.', '{"question":"Tunajifunza nini kutokana na kifungu?","wrong_answer":"Wanafunzi waliimba na bendera ikapandishwa.","correct_answer":"Tunapaswa kuipenda na kuiheshimu nchi yetu."}'::jsonb, 'The lesson question sounds like a what-happened question to the child.', 'The question "Tunajifunza nini kutokana na kifungu?" with "Wanafunzi waliimba na bendera ikapandishwa." among the options.', 'Start the answer with "Tunajifunza kwamba tunapaswa..."', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU.M3_UFM_OWN_T1', 'KISW.G3.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Answers from his own life instead of from the passage.', '{"question":"Wanafunzi husimamaje wimbo wa taifa unapoimbwa?","wrong_answer":"Mimi huimba nikiwa nimeketi nyumbani.","correct_answer":"Husimama wima kwa heshima."}'::jsonb, 'The child links the question to what he knows from home and does not check the text.', 'The question "Wanafunzi husimamaje wimbo wa taifa unapoimbwa?" with "Mimi huimba nikiwa nimeketi nyumbani." among the options.', 'Ask the child to point at the line in the passage that gives the answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T1_HATI_NADHIFU_KIFUNGU.HATI_NADHIFU.M3_HAT_DRAFT_T1', 'KISW.G3.KUANDI.T1_HATI_NADHIFU_KIFUNGU.HATI_NADHIFU', 'Hands in the first draft with crossings and does not make a clean copy.', '{"question":"Ni hatua gani ya mwisho ya kuandika kifungu?","wrong_answer":"nakala ya kwanza","correct_answer":"nakala safi"}'::jsonb, 'The child thinks writing ends when the words are down; the steps maandalizi, nakala ya kwanza, urekebishaji, nakala safi are new.', 'The question "Ni hatua gani ya mwisho ya kuandika kifungu?" with "nakala ya kwanza" among the options.', 'Show the four steps as four boxes; the child ticks each one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T1_HATI_NADHIFU_KIFUNGU.HATI_NADHIFU.M3_HAT_COPY_T1', 'KISW.G3.KUANDI.T1_HATI_NADHIFU_KIFUNGU.HATI_NADHIFU', 'Leaves out words or a whole line when copying.', '{"question":"Nakili: \"Kenya ni nchi yetu nzuri.\"","wrong_answer":"Kenya nchi yetu nzuri.","correct_answer":"Kenya ni nchi yetu nzuri."}'::jsonb, 'The child copies letter by letter and loses his place when looking back.', 'The question "Nakili: "Kenya ni nchi yetu nzuri."" with "Kenya nchi yetu nzuri." among the options.', 'Copy phrase by phrase, moving a finger along the line; read the copy back against the original.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T1_HATI_NADHIFU_KIFUNGU.HATI_NADHIFU.M3_HAT_SPACE_T1', 'KISW.G3.KUANDI.T1_HATI_NADHIFU_KIFUNGU.HATI_NADHIFU', 'Leaves no space between words (Mamaanapika).', '{"question":"Ni lipi limeandikwa vizuri?","wrong_answer":"Mamaanapikachakula.","correct_answer":"Mama anapika chakula."}'::jsonb, 'Spoken Kiswahili runs words together; the child writes the stream as he hears it.', 'The question "Ni lipi limeandikwa vizuri?" with "Mamaanapikachakula." among the options.', 'Put a finger space after every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T1_HATI_NADHIFU_KIFUNGU.HATI_NADHIFU.M3_HAT_TURN_T1', 'KISW.G3.KUANDI.T1_HATI_NADHIFU_KIFUNGU.HATI_NADHIFU', 'Turns b and d (or p and q) round: dada written "baba" or "bada".', '{"question":"Andika neno \"dada\".","wrong_answer":"bada","correct_answer":"dada"}'::jsonb, 'Mirror letters are common in early writing; the child has not fixed the direction.', 'The question "Andika neno "dada"." with "bada" among the options.', 'Teach d as "c then a tall line"; trace it in sand.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T1_HATI_NADHIFU_KIFUNGU.HATI_NADHIFU.M3_HAT_LINE_T1', 'KISW.G3.KUANDI.T1_HATI_NADHIFU_KIFUNGU.HATI_NADHIFU', 'Writes letters floating above the line or of mixed sizes, so the line goes up and down.', '{"question":"Maandishi nadhifu yanakaa wapi?","wrong_answer":"popote kwenye ukurasa","correct_answer":"juu ya mstari, herufi zikiwa na ukubwa sawa"}'::jsonb, 'The child writes fast and does not look at the line.', 'The question "Maandishi nadhifu yanakaa wapi?" with "popote kwenye ukurasa" among the options.', 'Trace the line with a finger first; every letter sits on it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T1_MATUMIZI_YA_YEYE_NA_.NAFSI.M3_SAR_PREFIX_T1', 'KISW.G3.SARUFI.T1_MATUMIZI_YA_YEYE_NA_.NAFSI', 'The pronoun and the subject marker on the verb do not agree (Wao anacheza).', '{"question":"Jaza: Wao ___ (cheza) mpira.","wrong_answer":"anacheza","correct_answer":"wanacheza"}'::jsonb, 'The child learns the pronoun as a word and the verb as a fixed form; he has not seen that the verb changes with the person.', 'The question "Jaza: Wao ___ (cheza) mpira." with "anacheza" among the options.', 'Colour the pronoun and the verb''s first syllable the same colour: yeye a-, wao wa-, mimi ni-, sisi tu-, wewe u-, nyinyi m-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T1_MATUMIZI_YA_YEYE_NA_.NAFSI.M3_SAR_NUMBER_T1', 'KISW.G3.SARUFI.T1_MATUMIZI_YA_YEYE_NA_.NAFSI', 'Uses the one-person pronoun for many people, or the reverse.', '{"question":"Juma na Ali wanasoma. ___ wanasoma.","wrong_answer":"Yeye","correct_answer":"Wao"}'::jsonb, 'The child has not linked the pronoun pair to one and many.', 'The question "Juma na Ali wanasoma. ___ wanasoma." with "Yeye" among the options.', 'Point at one child, then at a group, saying the right pronoun each time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T1_MATUMIZI_YA_YEYE_NA_.NAFSI.M3_SAR_GENDER_T1', 'KISW.G3.SARUFI.T1_MATUMIZI_YA_YEYE_NA_.NAFSI', 'Thinks yeye is for a boy only and looks for another word for a girl (English he/she).', '{"question":"Amina anapika. Mtaje kwa neno moja: ___ anapika.","wrong_answer":"Wao","correct_answer":"Yeye"}'::jsonb, 'English separates he and she; Kiswahili yeye is any one person.', 'The question "Amina anapika. Mtaje kwa neno moja: ___ anapika." with "Wao" among the options.', 'Use yeye for Amina and for Juma in the same lesson; ask the class to find the difference (there is none).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T1_MATUMIZI_YA_YEYE_NA_.NAFSI.M3_SAR_PERSON_T1', 'KISW.G3.SARUFI.T1_MATUMIZI_YA_YEYE_NA_.NAFSI', 'Repeats the pronoun of the question in the answer (Wewe unaenda wapi? Wewe ninaenda sokoni.) instead of switching to mimi.', '{"question":"Mama anauliza: \"Baba yuko wapi?\" Unajibu:","wrong_answer":"Wewe yuko shambani.","correct_answer":"Yeye yuko shambani."}'::jsonb, 'The child copies the words he heard; changing person between speakers is new.', 'The question "Mama anauliza: "Baba yuko wapi?" Unajibu:" with "Wewe yuko shambani." among the options.', 'Ask and answer in pairs with a pointing finger: wewe points out, mimi points to the chest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T2_MATAMSHI_BORA_VOKALI.VOKALI_KONSONANTI.M3_VOK_Y_T2', 'KISW.G3.KUSIKI.T2_MATAMSHI_BORA_VOKALI.VOKALI_KONSONANTI', 'Counts y (and sometimes w) as a vowel.', '{"question":"Ni zipi ni irabu za Kiswahili?","wrong_answer":"a, e, i, o, u, y","correct_answer":"a, e, i, o, u"}'::jsonb, 'English lessons teach that y is "sometimes a vowel"; Kiswahili has five vowels only.', 'The question "Ni zipi ni irabu za Kiswahili?" with "a, e, i, o, u, y" among the options.', 'Sort letter cards into two baskets; y and w go with the consonants.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T2_MATAMSHI_BORA_VOKALI.VOKALI_KONSONANTI.M3_VOK_DIGRAPH_T2', 'KISW.G3.KUSIKI.T2_MATAMSHI_BORA_VOKALI.VOKALI_KONSONANTI', 'Counts a two-letter consonant (sh, ch, ny, dh) as two sounds.', '{"question":"Neno \"shamba\" linaanza na konsonanti ngapi?","wrong_answer":"mbili: s na h","correct_answer":"moja: sh"}'::jsonb, 'The child counts letters, not sounds.', 'The question "Neno "shamba" linaanza na konsonanti ngapi?" with "mbili: s na h" among the options.', 'Say the sound alone (sh!) and show it is one sound on one card.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T2_MATAMSHI_BORA_VOKALI.VOKALI_KONSONANTI.M3_VOK_NAME_T2', 'KISW.G3.KUSIKI.T2_MATAMSHI_BORA_VOKALI.VOKALI_KONSONANTI', 'Says the English letter name for a vowel (i as "ai", e as "ii").', '{"question":"Irabu \"i\" katika neno \"iko\" inatamkwaje?","wrong_answer":"ai","correct_answer":"i"}'::jsonb, 'English letter names were learnt alongside; the child uses them for the Kiswahili sound.', 'The question "Irabu "i" katika neno "iko" inatamkwaje?" with "ai" among the options.', 'Sing the Kiswahili vowel song with each vowel sound held.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T2_MATAMSHI_BORA_VOKALI.VOKALI_KONSONANTI.M3_VOK_UO_T2', 'KISW.G3.KUSIKI.T2_MATAMSHI_BORA_VOKALI.VOKALI_KONSONANTI', 'Mixes u and o (or i and e) in speech and writing (kuku said and written koko).', '{"question":"Ni lipi sahihi kwa ndege wa nyumbani anayetaga mayai?","wrong_answer":"koko","correct_answer":"kuku"}'::jsonb, 'Some Kenyan first languages have seven vowels, with sounds between u and o and between i and e; the child hears the Kiswahili vowels through them.', 'The question "Ni lipi sahihi kwa ndege wa nyumbani anayetaga mayai?" with "koko" among the options.', 'Mouth shapes with a mirror: round and small for u, round and open for o.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T2_MATAMSHI_BORA_VOKALI.VOKALI_KONSONANTI.M3_VOK_NG_T2', 'KISW.G3.KUSIKI.T2_MATAMSHI_BORA_VOKALI.VOKALI_KONSONANTI', 'Does not tell ng'' from ng (ngoma and ng''ombe start with the same sound to the child).', '{"question":"Ni neno lipi lina sauti ng'' mwanzoni?","wrong_answer":"ngoma","correct_answer":"ng''ombe"}'::jsonb, 'Ng'' has no /g/ after the nasal; the child hears both as one.', 'The question "Ni neno lipi lina sauti ng'' mwanzoni?" with "ngoma" among the options.', 'Say ngoma and ng''ombe with a hand on the throat: the /g/ of ngoma is felt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M3_UFS_SOUND_T2', 'KISW.G3.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads the target word wrongly: "bwana" as "buwana".', '{"question":"Neno \"bwana\" linasomwa vipi?","wrong_answer":"buwana","correct_answer":"bwana"}'::jsonb, 'The child reads the letters with the sounds of his first language, or adds a vowel to break the cluster.', 'The question "Neno "bwana" linasomwa vipi?" with "buwana" among the options.', 'Pick out the target words before reading; practise them on cards, then read the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M3_UFS_WORD_T2', 'KISW.G3.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Bwana Juma analima shamba la mahindi.\"?","wrong_answer":"Bwana ... Juma ... analima ... shamba ... la ... mahindi.","correct_answer":"Bwana Juma analima shamba la mahindi."}'::jsonb, 'The child is still decoding each word; he has not yet read a group of words as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Bwana Juma analima shamba la mahindi."?" with "Bwana ... Juma ... analima ... shamba ... la ... mahindi." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it in one breath.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M3_UFS_QUIET_T2', 'KISW.G3.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads so softly (or so loudly, shouting) that the class cannot follow.', '{"question":"Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?","wrong_answer":"ya chini ili nisikosee mbele ya wenzangu","correct_answer":"ya kusikika na wote darasani, bila kupiga kelele"}'::jsonb, 'Shyness, or the belief that reading well means reading loud.', 'The question "Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?" with "ya chini ili nisikosee mbele ya wenzangu" among the options.', 'Stand the reader at the front and a listener at the back: the listener raises a hand when he hears every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M3_UFS_PACE_T2', 'KISW.G3.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Kasi ifaayo ya kusoma kifungu ni ipi?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, karibu maneno 47 kwa dakika"}'::jsonb, 'Reading races in class reward speed; nobody asked whether the listeners understood.', 'The question "Kasi ifaayo ya kusoma kifungu ni ipi?" with "haraka iwezekanavyo" among the options.', 'Time two readings, one very fast and one at speaking pace; the listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M3_UFS_MARK_T2', 'KISW.G3.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads a question in the flat voice of a statement and runs on through the koma and kikomo.', '{"question":"Sentensi \"Je, umeona fyekeo la Bwana Juma?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the marks.', 'The question "Sentensi "Je, umeona fyekeo la Bwana Juma?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that fits each reading; clap at each kikomo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T2_HATI_NADHIFU.HATI_NADHIFU.M3_HAT_CAPSTART_T2', 'KISW.G3.KUANDI.T2_HATI_NADHIFU.HATI_NADHIFU', 'Starts a sentence or a name with a small letter.', '{"question":"Andika kwa usahihi: juma na amina wanalima shambani.","wrong_answer":"juma na amina wanalima shambani.","correct_answer":"Juma na Amina wanalima shambani."}'::jsonb, 'The child copies words, not sentences; the rule that a sentence and a name begin with a capital is not yet used.', 'The question "Andika kwa usahihi: juma na amina wanalima shambani." with "juma na amina wanalima shambani." among the options.', 'Circle the first letter of each sentence and each name in a passage in red.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T2_HATI_NADHIFU.HATI_NADHIFU.M3_HAT_CAPMID_T2', 'KISW.G3.KUANDI.T2_HATI_NADHIFU.HATI_NADHIFU', 'Puts capital letters in the middle of words (JuMa, Kitabu KiKubwa).', '{"question":"Ni lipi limeandikwa vizuri?","wrong_answer":"JuMa ANakula","correct_answer":"Juma anakula"}'::jsonb, 'Some capitals (K, M, S) are easier to form than the small letter, so the child uses them anywhere.', 'The question "Ni lipi limeandikwa vizuri?" with "JuMa ANakula" among the options.', 'Sort letter cards: capital only at the start; the rest small.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T2_HATI_NADHIFU.HATI_NADHIFU.M3_HAT_SPACE_T2', 'KISW.G3.KUANDI.T2_HATI_NADHIFU.HATI_NADHIFU', 'Leaves no space between words (Mamaanapika).', '{"question":"Ni lipi limeandikwa vizuri?","wrong_answer":"Mamaanapikachakula.","correct_answer":"Mama anapika chakula."}'::jsonb, 'Spoken Kiswahili runs words together; the child writes the stream as he hears it.', 'The question "Ni lipi limeandikwa vizuri?" with "Mamaanapikachakula." among the options.', 'Put a finger space after every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T2_HATI_NADHIFU.HATI_NADHIFU.M3_HAT_TURN_T2', 'KISW.G3.KUANDI.T2_HATI_NADHIFU.HATI_NADHIFU', 'Turns b and d (or p and q) round: dada written "baba" or "bada".', '{"question":"Andika neno \"dada\".","wrong_answer":"bada","correct_answer":"dada"}'::jsonb, 'Mirror letters are common in early writing; the child has not fixed the direction.', 'The question "Andika neno "dada"." with "bada" among the options.', 'Teach d as "c then a tall line"; trace it in sand.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T2_HATI_NADHIFU.HATI_NADHIFU.M3_HAT_LINE_T2', 'KISW.G3.KUANDI.T2_HATI_NADHIFU.HATI_NADHIFU', 'Writes letters floating above the line or of mixed sizes, so the line goes up and down.', '{"question":"Maandishi nadhifu yanakaa wapi?","wrong_answer":"popote kwenye ukurasa","correct_answer":"juu ya mstari, herufi zikiwa na ukubwa sawa"}'::jsonb, 'The child writes fast and does not look at the line.', 'The question "Maandishi nadhifu yanakaa wapi?" with "popote kwenye ukurasa" among the options.', 'Trace the line with a finger first; every letter sits on it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T2_UMOJA_NA_WINGI_WA_SE.UMOJA_WINGI.M3_SAR_WRONGCLASS_T2', 'KISW.G3.SARUFI.T2_UMOJA_NA_WINGI_WA_SE.UMOJA_WINGI', 'Makes the plural with the prefix of another noun class (kitabu -> watabu).', '{"question":"Wingi wa \"Kiatu kimechafuka\" ni?","wrong_answer":"Wiatu wamechafuka.","correct_answer":"Viatu vimechafuka."}'::jsonb, 'The child knows that wa- makes people plural and uses it for everything; the ngeli of the noun is not yet known.', 'The question "Wingi wa "Kiatu kimechafuka" ni?" with "Wiatu wamechafuka." among the options.', 'Sort noun cards into ngeli families (m-wa, ki-vi, li-ma, n-n) and say each plural aloud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T2_UMOJA_NA_WINGI_WA_SE.UMOJA_WINGI.M3_SAR_AGREE_T2', 'KISW.G3.SARUFI.T2_UMOJA_NA_WINGI_WA_SE.UMOJA_WINGI', 'Changes the noun but not the verb or the word that agrees with it (Vitabu kimeanguka).', '{"question":"Andika kwa wingi: Mti umeanguka.","wrong_answer":"Miti umeanguka.","correct_answer":"Miti imeanguka."}'::jsonb, 'The child changes the word he was asked to change and stops there.', 'The question "Andika kwa wingi: Mti umeanguka." with "Miti umeanguka." among the options.', 'Colour the noun prefix and the verb prefix the same; read the sentence and check every coloured part.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T2_UMOJA_NA_WINGI_WA_SE.UMOJA_WINGI.M3_SAR_NUMWORD_T2', 'KISW.G3.SARUFI.T2_UMOJA_NA_WINGI_WA_SE.UMOJA_WINGI', 'Shows the plural only with a number word and leaves the noun singular (kitabu mbili).', '{"question":"Wingi wa \"jembe moja\" ni?","wrong_answer":"jembe mbili","correct_answer":"majembe mawili"}'::jsonb, 'English and some first languages keep the noun and add a number; Kiswahili changes the noun and the number agrees.', 'The question "Wingi wa "jembe moja" ni?" with "jembe mbili" among the options.', 'Line up two books: the child says vitabu viwili; then three: vitabu vitatu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T2_UMOJA_NA_WINGI_WA_SE.UMOJA_WINGI.M3_SAR_NCLASS_T2', 'KISW.G3.SARUFI.T2_UMOJA_NA_WINGI_WA_SE.UMOJA_WINGI', 'Gives a noun of the n-n class a plural prefix (nyumba -> manyumba), or changes an irregular noun wrongly (jicho -> majicho).', '{"question":"Andika kwa wingi: Ng''ombe anakula nyasi.","wrong_answer":"Mang''ombe wanakula nyasi.","correct_answer":"Ng''ombe wanakula nyasi."}'::jsonb, 'The child expects every plural to look different; n-n nouns stay the same and some li-ma nouns change their stem.', 'The question "Andika kwa wingi: Ng''ombe anakula nyasi." with "Mang''ombe wanakula nyasi." among the options.', 'Keep a short list of the same-in-both nouns (nyumba, ndizi, kalamu) and the irregular ones (jicho - macho, jino - meno).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T2_UMOJA_NA_WINGI_WA_SE.UMOJA_WINGI.M3_SAR_REVERSE_T2', 'KISW.G3.SARUFI.T2_UMOJA_NA_WINGI_WA_SE.UMOJA_WINGI', 'Takes the plural form for the singular (miti for one tree, vitabu for one book).', '{"question":"Ni sentensi ipi iko katika umoja?","wrong_answer":"Miti imeota.","correct_answer":"Mti umeota."}'::jsonb, 'The child heard the plural more often (a tree is usually among trees) and learnt it as the name.', 'The question "Ni sentensi ipi iko katika umoja?" with "Miti imeota." among the options.', 'Hold one object, then many; the child names each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T3_MANENO_YA_HESHIMA_NA.HESHIMA.M3_HES_POLE_T3', 'KISW.G3.KUSIKI.T3_MANENO_YA_HESHIMA_NA.HESHIMA', 'Says samahani when someone else is hurt by accident, where pole (sympathy) is meant.', '{"question":"Rafiki ameanguka mwenyewe uwanjani. Unamwambia nini?","wrong_answer":"Samahani","correct_answer":"Pole"}'::jsonb, 'English "sorry" covers both apology and sympathy; Kiswahili separates them: samahani when I did wrong, pole when you suffer.', 'The question "Rafiki ameanguka mwenyewe uwanjani. Unamwambia nini?" with "Samahani" among the options.', 'Two pictures: I stepped on your foot (samahani); you fell by yourself (pole). The child names each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T3_MANENO_YA_HESHIMA_NA.HESHIMA.M3_HES_KARIBU_T3', 'KISW.G3.KUSIKI.T3_MANENO_YA_HESHIMA_NA.HESHIMA', 'Answers "Asante" with "Asante" instead of "Karibu" (or "Si neno").', '{"question":"Ulimpa rafiki kalamu, akasema \"Asante.\" Unajibu nini?","wrong_answer":"Asante","correct_answer":"Karibu"}'::jsonb, 'The child echoes the polite word he has just heard.', 'The question "Ulimpa rafiki kalamu, akasema "Asante." Unajibu nini?" with "Asante" among the options.', 'Practise the pair with two children: one gives, one thanks, the giver answers Karibu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T3_MANENO_YA_HESHIMA_NA.HESHIMA.M3_HES_COMMAND_T3', 'KISW.G3.KUSIKI.T3_MANENO_YA_HESHIMA_NA.HESHIMA', 'Asks with a bare command (Nipe maji!) without tafadhali or naomba.', '{"question":"Unataka maji kutoka kwa mama. Unasemaje?","wrong_answer":"Nipe maji!","correct_answer":"Mama, tafadhali naomba maji."}'::jsonb, 'At home and in play the child hears short commands and copies them to adults.', 'The question "Unataka maji kutoka kwa mama. Unasemaje?" with "Nipe maji!" among the options.', 'Say both versions; the child says which one makes mama want to help.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T3_MANENO_YA_HESHIMA_NA.HESHIMA.M3_HES_TITLE_T3', 'KISW.G3.KUSIKI.T3_MANENO_YA_HESHIMA_NA.HESHIMA', 'Calls an adult by the bare first name without a title (Mwalimu, Mama, Baba, Bi., Bw.).', '{"question":"Unamwita mwalimu wako, Bi. Akinyi. Unasemaje?","wrong_answer":"Akinyi, njoo!","correct_answer":"Mwalimu, tafadhali njoo."}'::jsonb, 'Children call each other by name and carry the habit to adults.', 'The question "Unamwita mwalimu wako, Bi. Akinyi. Unasemaje?" with "Akinyi, njoo!" among the options.', 'Make title cards (Mwalimu, Mama, Babu, Daktari); the child puts one before each name.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T3_MANENO_YA_HESHIMA_NA.HESHIMA.M3_HES_POLEREPLY_T3', 'KISW.G3.KUSIKI.T3_MANENO_YA_HESHIMA_NA.HESHIMA', 'Answers "Pole" with "Pole" instead of "Asante".', '{"question":"Rafiki anakuambia \"Pole kwa kuumia.\" Unajibu?","wrong_answer":"Pole","correct_answer":"Asante"}'::jsonb, 'The child echoes the word, as with greetings.', 'The question "Rafiki anakuambia "Pole kwa kuumia." Unajibu?" with "Pole" among the options.', 'Act it: one child is hurt, the other says pole, the hurt one says asante.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.UFAHAMU.M3_UFM_WORD_T3', 'KISW.G3.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Gives "kusherehekea" the meaning of a word that looks or sounds like it.', '{"question":"Soma: \"Mwezi wa Desemba, Baraka alisherehekea siku yake ya kuzaliwa. Alitimiza miaka minane. Mama alimwokea keki, na marafiki zake wakamwimbia.\" Neno \"kusherehekea\" lina maana gani?","wrong_answer":"kusahau","correct_answer":"kufanya sherehe kwa furaha"}'::jsonb, 'The child matches the word to a known one by its look instead of reading the sentence around it.', 'The question "Soma: "Mwezi wa Desemba, Baraka alisherehekea siku yake ya kuzaliwa. Alitimiza miaka minane. Mama alimwokea keki, na marafiki zake wakamwimbia." Neno "kusherehekea" lina maana gani?" with "kusahau" among the options.', 'Cover the word; the child says what word would fit the sentence, then uncovers it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.UFAHAMU.M3_UFM_MSG_T3', 'KISW.G3.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Gives one detail of the passage as its message.', '{"question":"Ujumbe wa kifungu ni upi?","wrong_answer":"Mama alioka keki.","correct_answer":"Siku ya kuzaliwa ni siku ya furaha ya kukumbuka tulipozaliwa."}'::jsonb, 'The detail is what the child remembers best; he has not been asked what the writer wants us to know.', 'The question "Ujumbe wa kifungu ni upi?" with "Mama alioka keki." among the options.', 'Ask two questions side by side: "Nini kilitokea?" and "Kifungu kinatuambia nini?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.UFAHAMU.M3_UFM_GUESS_T3', 'KISW.G3.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Predicts something the passage gives no clue for.', '{"question":"Desemba ijayo Baraka atatimiza miaka mingapi?","wrong_answer":"miaka minane tena","correct_answer":"miaka tisa"}'::jsonb, 'Prediction is taken as free imagination; the child has not been shown that clues in the text and picture point the way.', 'The question "Desemba ijayo Baraka atatimiza miaka mingapi?" with "miaka minane tena" among the options.', 'Underline the clue words; the guess must fit them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.UFAHAMU.M3_UFM_LESSON_T3', 'KISW.G3.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Retells what happened when asked for the lesson.', '{"question":"Tunajifunza nini kutokana na kifungu?","wrong_answer":"Marafiki walimwimbia Baraka.","correct_answer":"Tunapaswa kufurahi pamoja na marafiki zetu."}'::jsonb, 'The lesson question sounds like a what-happened question to the child.', 'The question "Tunajifunza nini kutokana na kifungu?" with "Marafiki walimwimbia Baraka." among the options.', 'Start the answer with "Tunajifunza kwamba tunapaswa..."', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.UFAHAMU.M3_UFM_OWN_T3', 'KISW.G3.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Answers from his own life instead of from the passage.', '{"question":"Baraka alizaliwa mwezi gani?","wrong_answer":"Mimi nilizaliwa mwezi wa Machi.","correct_answer":"Desemba"}'::jsonb, 'The child links the question to what he knows from home and does not check the text.', 'The question "Baraka alizaliwa mwezi gani?" with "Mimi nilizaliwa mwezi wa Machi." among the options.', 'Ask the child to point at the line in the passage that gives the answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T3_HATI_NADHIFU.HATI_NADHIFU.M3_HAT_TALL_T3', 'KISW.G3.KUANDI.T3_HATI_NADHIFU.HATI_NADHIFU', 'Writes the tall small letters (b, d, h, k, l) short, so h looks like n.', '{"question":"Andika neno \"habari\". Ni lipi limeandikwa vizuri?","wrong_answer":"nabari","correct_answer":"habari"}'::jsonb, 'The child does not use the lines of the book: tall letters must reach the top line.', 'The question "Andika neno "habari". Ni lipi limeandikwa vizuri?" with "nabari" among the options.', 'Write on three-line paper; the child colours the part of h that goes up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T3_HATI_NADHIFU.HATI_NADHIFU.M3_HAT_SIZE_T3', 'KISW.G3.KUANDI.T3_HATI_NADHIFU.HATI_NADHIFU', 'Writes some small letters as big as capitals (kiti written kiTi or KITI).', '{"question":"Ni neno lipi limeandikwa kwa herufi ndogo vizuri?","wrong_answer":"KITI","correct_answer":"kiti"}'::jsonb, 'Capitals were learnt first in pre-primary and feel safer to write.', 'The question "Ni neno lipi limeandikwa kwa herufi ndogo vizuri?" with "KITI" among the options.', 'Compare k/K, s/S, t/T on cards; the child picks the small one for the middle of a word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T3_HATI_NADHIFU.HATI_NADHIFU.M3_HAT_SPACE_T3', 'KISW.G3.KUANDI.T3_HATI_NADHIFU.HATI_NADHIFU', 'Leaves no space between words (Mamaanapika).', '{"question":"Ni lipi limeandikwa vizuri?","wrong_answer":"Mamaanapikachakula.","correct_answer":"Mama anapika chakula."}'::jsonb, 'Spoken Kiswahili runs words together; the child writes the stream as he hears it.', 'The question "Ni lipi limeandikwa vizuri?" with "Mamaanapikachakula." among the options.', 'Put a finger space after every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T3_HATI_NADHIFU.HATI_NADHIFU.M3_HAT_TURN_T3', 'KISW.G3.KUANDI.T3_HATI_NADHIFU.HATI_NADHIFU', 'Turns b and d (or p and q) round: dada written "baba" or "bada".', '{"question":"Andika neno \"dada\".","wrong_answer":"bada","correct_answer":"dada"}'::jsonb, 'Mirror letters are common in early writing; the child has not fixed the direction.', 'The question "Andika neno "dada"." with "bada" among the options.', 'Teach d as "c then a tall line"; trace it in sand.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T3_HATI_NADHIFU.HATI_NADHIFU.M3_HAT_LINE_T3', 'KISW.G3.KUANDI.T3_HATI_NADHIFU.HATI_NADHIFU', 'Writes letters floating above the line or of mixed sizes, so the line goes up and down.', '{"question":"Maandishi nadhifu yanakaa wapi?","wrong_answer":"popote kwenye ukurasa","correct_answer":"juu ya mstari, herufi zikiwa na ukubwa sawa"}'::jsonb, 'The child writes fast and does not look at the line.', 'The question "Maandishi nadhifu yanakaa wapi?" with "popote kwenye ukurasa" among the options.', 'Trace the line with a finger first; every letter sits on it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T3_MATUMIZI_YA_MANENO_Y.VIONYESHI.M3_SAR_CLASSDEM_T3', 'KISW.G3.SARUFI.T3_MATUMIZI_YA_MANENO_Y.VIONYESHI', 'Uses the people word (huyu, yule) for a thing (kiti huyu).', '{"question":"Jaza: Kiti ___ (kilicho mbali) ni kizuri.","wrong_answer":"yule","correct_answer":"kile"}'::jsonb, 'Huyu was the first pointing word learnt; the child uses it for anything.', 'The question "Jaza: Kiti ___ (kilicho mbali) ni kizuri." with "yule" among the options.', 'Point at a child (huyu) and at a chair (hiki); then sort pictures by the pointing word they take.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T3_MATUMIZI_YA_MANENO_Y.VIONYESHI.M3_SAR_NUMDEM_T3', 'KISW.G3.SARUFI.T3_MATUMIZI_YA_MANENO_Y.VIONYESHI', 'Uses the one-thing pointing word with a plural noun (watoto huyu).', '{"question":"Jaza: Watoto ___ (walio mbali) wanacheza.","wrong_answer":"yule","correct_answer":"wale"}'::jsonb, 'The child changes the noun but not the pointing word.', 'The question "Jaza: Watoto ___ (walio mbali) wanacheza." with "yule" among the options.', 'Pair the forms on cards: huyu-hawa, yule-wale, hiki-hivi, hili-haya.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T3_MATUMIZI_YA_MANENO_Y.VIONYESHI.M3_SAR_DIST_T3', 'KISW.G3.SARUFI.T3_MATUMIZI_YA_MANENO_Y.VIONYESHI', 'Mixes near and far pointing words (huyu for someone far away; yule for someone close).', '{"question":"Mtoto yuko karibu nawe. Unasema: Mtoto ___ ni rafiki yangu.","wrong_answer":"yule","correct_answer":"huyu"}'::jsonb, 'The child has not linked the forms to distance from the speaker.', 'The question "Mtoto yuko karibu nawe. Unasema: Mtoto ___ ni rafiki yangu." with "yule" among the options.', 'Stand near one child and far from another; point and say huyu and yule; then swap places.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T3_MATUMIZI_YA_MANENO_Y.VIONYESHI.M3_SAR_HII_T3', 'KISW.G3.SARUFI.T3_MATUMIZI_YA_MANENO_Y.VIONYESHI', 'Uses hii for every noun (kitabu hii, mtoto hii), as in town Kiswahili.', '{"question":"Jaza: Mwalimu ___ (aliye mbali) anafundisha.","wrong_answer":"hii","correct_answer":"yule"}'::jsonb, 'Hii is the pointing word heard most in town speech, where the noun class is dropped.', 'The question "Jaza: Mwalimu ___ (aliye mbali) anafundisha." with "hii" among the options.', 'Read pairs aloud: kitabu hiki, mtoto huyu, nyumba hii; the child hears the match.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T4_MATAMSHI_BORA.MATAMSHI.M3_SAU_NEAR_T4', 'KISW.G3.KUSIKI.T4_MATAMSHI_BORA.MATAMSHI', 'Says /s/ for /sh/, so "shamba" becomes "samba".', '{"question":"Mwalimu anasema \"shamba\". Neno lipi limetamkwa vizuri?","wrong_answer":"samba","correct_answer":"shamba"}'::jsonb, 'Many Kenyan first languages have no /sh/, or do not separate it from /s/; the child puts in the home sound.', 'The question "Mwalimu anasema "shamba". Neno lipi limetamkwa vizuri?" with "samba" among the options.', 'Say the two side by side, slowly, watching the mouth; the child holds up a card for the sound he hears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T4_MATAMSHI_BORA.MATAMSHI.M3_SAU_VOWEL_T4', 'KISW.G3.KUSIKI.T4_MATAMSHI_BORA.MATAMSHI', 'Pushes a vowel into the cluster, so "vyakula" is said "viyakula".', '{"question":"Tamka neno \"vyakula\". Ni lipi sahihi?","wrong_answer":"viyakula","correct_answer":"vyakula"}'::jsonb, 'In the child''s first language, or in English loan habits, two consonants rarely sit together; he breaks them with a vowel.', 'The question "Tamka neno "vyakula". Ni lipi sahihi?" with "viyakula" among the options.', 'Say the cluster in one beat, then the word; clap once for the cluster syllable.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T4_MATAMSHI_BORA.MATAMSHI.M3_SAU_DROP_T4', 'KISW.G3.KUSIKI.T4_MATAMSHI_BORA.MATAMSHI', 'Drops part of the target sound, so "kipya" becomes "kipa".', '{"question":"Neno \"kipya\" limeandikwa au kutamkwa vipi kwa usahihi?","wrong_answer":"kipa","correct_answer":"kipya"}'::jsonb, 'The second part of the sound (the w or y glide, or the soft nasal) is quick and quiet; the child does not hear it and leaves it out.', 'The question "Neno "kipya" limeandikwa au kutamkwa vipi kwa usahihi?" with "kipa" among the options.', 'Stretch the syllable slowly (p-y-a), then say it fast; the child copies.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T4_MATAMSHI_BORA.MATAMSHI.M3_SAU_SYLL_T4', 'KISW.G3.KUSIKI.T4_MATAMSHI_BORA.MATAMSHI', 'Splits "kipya" by letters rather than by syllables (each Kiswahili syllable ends in a vowel).', '{"question":"Neno \"kipya\" lina silabi zipi?","wrong_answer":"k-i-p-y-a","correct_answer":"ki-pya"}'::jsonb, 'The child has learnt letters one by one and has not been shown that a syllable is a sound that ends in a vowel.', 'The question "Neno "kipya" lina silabi zipi?" with "k-i-p-y-a" among the options.', 'Clap the word: one clap per vowel; the consonants go with the vowel after them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T4_MATAMSHI_BORA.MATAMSHI.M3_SAU_PICK_T4', 'KISW.G3.KUSIKI.T4_MATAMSHI_BORA.MATAMSHI', 'Picks a word with no target sound when asked for one that has it.', '{"question":"Ni neno lipi lina sauti /py/, /vy/, /sh/?","wrong_answer":"kalamu","correct_answer":"vyakula"}'::jsonb, 'The child looks at the first letter or the picture, not at the sound.', 'The question "Ni neno lipi lina sauti /py/, /vy/, /sh/?" with "kalamu" among the options.', 'Underline the target sound in each word on the card before choosing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI.M3_UFS_SOUND_T4', 'KISW.G3.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI', 'Reads the target word wrongly: "vyombo" as "viombo".', '{"question":"Neno \"vyombo\" linasomwa vipi?","wrong_answer":"viombo","correct_answer":"vyombo"}'::jsonb, 'The child reads the letters with the sounds of his first language, or adds a vowel to break the cluster.', 'The question "Neno "vyombo" linasomwa vipi?" with "viombo" among the options.', 'Pick out the target words before reading; practise them on cards, then read the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI.M3_UFS_WORD_T4', 'KISW.G3.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Fundi alitengeneza kiti kipya.\"?","wrong_answer":"Fundi ... alitengeneza ... kiti ... kipya.","correct_answer":"Fundi alitengeneza kiti kipya."}'::jsonb, 'The child is still decoding each word; he has not yet read a group of words as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Fundi alitengeneza kiti kipya."?" with "Fundi ... alitengeneza ... kiti ... kipya." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it in one breath.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI.M3_UFS_QUIET_T4', 'KISW.G3.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI', 'Reads so softly (or so loudly, shouting) that the class cannot follow.', '{"question":"Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?","wrong_answer":"ya chini ili nisikosee mbele ya wenzangu","correct_answer":"ya kusikika na wote darasani, bila kupiga kelele"}'::jsonb, 'Shyness, or the belief that reading well means reading loud.', 'The question "Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?" with "ya chini ili nisikosee mbele ya wenzangu" among the options.', 'Stand the reader at the front and a listener at the back: the listener raises a hand when he hears every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI.M3_UFS_PACE_T4', 'KISW.G3.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Kasi ifaayo ya kusoma kifungu ni ipi?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, karibu maneno 49 kwa dakika"}'::jsonb, 'Reading races in class reward speed; nobody asked whether the listeners understood.', 'The question "Kasi ifaayo ya kusoma kifungu ni ipi?" with "haraka iwezekanavyo" among the options.', 'Time two readings, one very fast and one at speaking pace; the listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI.M3_UFS_MARK_T4', 'KISW.G3.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI', 'Reads a question in the flat voice of a statement and runs on through the koma and kikomo.', '{"question":"Sentensi \"Je, mpishi ameosha vyombo vyote?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the marks.', 'The question "Sentensi "Je, mpishi ameosha vyombo vyote?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that fits each reading; clap at each kikomo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T4_NAFASI_YA_PAMBIZO_KA.PAMBIZO_AYA.M3_NAF_MARGIN_T4', 'KISW.G3.KUANDI.T4_NAFASI_YA_PAMBIZO_KA.PAMBIZO_AYA', 'Writes into the margin, from the edge of the page.', '{"question":"Pambizo ni nini?","wrong_answer":"sehemu ya kuandikia kwanza","correct_answer":"nafasi iliyoachwa ukingoni mwa ukurasa bila maandishi"}'::jsonb, 'The child wants to fit more on the page and does not see the margin line as a rule.', 'The question "Pambizo ni nini?" with "sehemu ya kuandikia kwanza" among the options.', 'Colour the margin; nothing may enter the coloured strip.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T4_NAFASI_YA_PAMBIZO_KA.PAMBIZO_AYA.M3_NAF_NOAYA_T4', 'KISW.G3.KUANDI.T4_NAFASI_YA_PAMBIZO_KA.PAMBIZO_AYA', 'Writes everything in one block with no new aya.', '{"question":"Unaanza aya mpya lini?","wrong_answer":"sianzi; ninaandika kila kitu pamoja","correct_answer":"ninapoanza wazo jipya"}'::jsonb, 'The child has not been shown that a new idea gets a new aya.', 'The question "Unaanza aya mpya lini?" with "sianzi; ninaandika kila kitu pamoja" among the options.', 'Give a passage with two ideas; the child marks where the second starts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T4_NAFASI_YA_PAMBIZO_KA.PAMBIZO_AYA.M3_NAF_EVERYLINE_T4', 'KISW.G3.KUANDI.T4_NAFASI_YA_PAMBIZO_KA.PAMBIZO_AYA', 'Starts every sentence on a new line, as if each were an aya.', '{"question":"Kila sentensi ianze mstari mpya?","wrong_answer":"ndiyo","correct_answer":"hapana; sentensi za wazo moja hufuatana katika aya moja"}'::jsonb, 'Early copying from the board was one sentence a line.', 'The question "Kila sentensi ianze mstari mpya?" with "ndiyo" among the options.', 'Rewrite three sentences about one idea as one aya.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T4_NAFASI_YA_PAMBIZO_KA.PAMBIZO_AYA.M3_NAF_SPLIT_T4', 'KISW.G3.KUANDI.T4_NAFASI_YA_PAMBIZO_KA.PAMBIZO_AYA', 'Breaks a word at the end of a line in the middle of a syllable (mkul-ima).', '{"question":"Neno ni refu na mstari umeisha. Ni mgawanyo upi sahihi?","wrong_answer":"mkul-ima","correct_answer":"mku-lima"}'::jsonb, 'The child cuts where the space ends, not at a syllable.', 'The question "Neno ni refu na mstari umeisha. Ni mgawanyo upi sahihi?" with "mkul-ima" among the options.', 'Clap the syllables first; break only between two claps, with a dash.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T4_UMOJA_NA_WINGI_WA_SE.UMOJA_WINGI.M3_SAR_WRONGCLASS_T4', 'KISW.G3.SARUFI.T4_UMOJA_NA_WINGI_WA_SE.UMOJA_WINGI', 'Makes the plural with the prefix of another noun class (kitabu -> watabu).', '{"question":"Wingi wa \"Mwalimu anafundisha\" ni?","wrong_answer":"Mialimu inafundisha.","correct_answer":"Walimu wanafundisha."}'::jsonb, 'The child knows that wa- makes people plural and uses it for everything; the ngeli of the noun is not yet known.', 'The question "Wingi wa "Mwalimu anafundisha" ni?" with "Mialimu inafundisha." among the options.', 'Sort noun cards into ngeli families (m-wa, ki-vi, li-ma, n-n) and say each plural aloud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T4_UMOJA_NA_WINGI_WA_SE.UMOJA_WINGI.M3_SAR_AGREE_T4', 'KISW.G3.SARUFI.T4_UMOJA_NA_WINGI_WA_SE.UMOJA_WINGI', 'Changes the noun but not the verb or the word that agrees with it (Vitabu kimeanguka).', '{"question":"Andika kwa wingi: Daktari anatibu wagonjwa.","wrong_answer":"Madaktari anatibu wagonjwa.","correct_answer":"Madaktari wanatibu wagonjwa."}'::jsonb, 'The child changes the word he was asked to change and stops there.', 'The question "Andika kwa wingi: Daktari anatibu wagonjwa." with "Madaktari anatibu wagonjwa." among the options.', 'Colour the noun prefix and the verb prefix the same; read the sentence and check every coloured part.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T4_UMOJA_NA_WINGI_WA_SE.UMOJA_WINGI.M3_SAR_NCLASS_T4', 'KISW.G3.SARUFI.T4_UMOJA_NA_WINGI_WA_SE.UMOJA_WINGI', 'Gives a noun of the n-n class a plural prefix (nyumba -> manyumba), or changes an irregular noun wrongly (jicho -> majicho).', '{"question":"Andika kwa wingi: Jino linauma.","wrong_answer":"Majino yanauma.","correct_answer":"Meno yanauma."}'::jsonb, 'The child expects every plural to look different; n-n nouns stay the same and some li-ma nouns change their stem.', 'The question "Andika kwa wingi: Jino linauma." with "Majino yanauma." among the options.', 'Keep a short list of the same-in-both nouns (nyumba, ndizi, kalamu) and the irregular ones (jicho - macho, jino - meno).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T4_UMOJA_NA_WINGI_WA_SE.UMOJA_WINGI.M3_SAR_NUMWORD_T4', 'KISW.G3.SARUFI.T4_UMOJA_NA_WINGI_WA_SE.UMOJA_WINGI', 'Shows the plural only with a number word and leaves the noun singular (kitabu mbili).', '{"question":"Wingi wa \"mpishi mmoja\" ni?","wrong_answer":"mpishi wawili","correct_answer":"wapishi wawili"}'::jsonb, 'English and some first languages keep the noun and add a number; Kiswahili changes the noun and the number agrees.', 'The question "Wingi wa "mpishi mmoja" ni?" with "mpishi wawili" among the options.', 'Line up two books: the child says vitabu viwili; then three: vitabu vitatu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA.M3_SIK_DETAIL_T5', 'KISW.G3.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA', 'Gives a detail of the passage as its message.', '{"question":"Ujumbe wa kifungu ulichosikiliza ni upi?","wrong_answer":"Wanjiru alienda dukani.","correct_answer":"Tuangalie kulia na kushoto na kuvuka kwenye kivuko ili tuwe salama."}'::jsonb, 'The detail is the clearest thing the child remembers; he has not been asked what the passage teaches.', 'The question "Ujumbe wa kifungu ulichosikiliza ni upi?" with "Wanjiru alienda dukani." among the options.', 'After listening, ask "Kifungu kinatufundisha nini?" and compare it with "Nini kilitokea?".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA.M3_SIK_WORD_T5', 'KISW.G3.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA', 'Gives "kivuko" the meaning of a word that sounds like it.', '{"question":"Neno \"kivuko\" katika kifungu lina maana gani?","wrong_answer":"kivuli","correct_answer":"mahali palipotengwa pa kuvuka barabara"}'::jsonb, 'The child matches the sound of the word to one he knows instead of listening to the sentence around it.', 'The question "Neno "kivuko" katika kifungu lina maana gani?" with "kivuli" among the options.', 'Replay the sentence; the child tries each meaning in it and keeps the one that makes sense.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA.M3_SIK_SENT_T5', 'KISW.G3.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA', 'Makes a "sentence" that only repeats the word and shows no meaning (kivuko ni kivuko).', '{"question":"Ni sentensi ipi inaonyesha maana ya \"kivuko\"?","wrong_answer":"Kivuko ni kivuko.","correct_answer":"Tulivuka barabara kwenye kivuko cha watembea kwa miguu."}'::jsonb, 'The child thinks any sentence with the word in it is enough.', 'The question "Ni sentensi ipi inaonyesha maana ya "kivuko"?" with "Kivuko ni kivuko." among the options.', 'Ask: if your friend did not know the word, would your sentence tell him what it means?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA.M3_SIK_ORDER_T5', 'KISW.G3.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA', 'Retells the events out of order.', '{"question":"Panga matukio ya kifungu kama yalivyotokea.","wrong_answer":"Gari lilisimama ghafla, Wanjiru alienda dukani, alivuka barabara bila kuangalia","correct_answer":"Wanjiru alienda dukani, alivuka barabara bila kuangalia, gari likasimama ghafla"}'::jsonb, 'The child remembers the most exciting event and tells it first.', 'The question "Panga matukio ya kifungu kama yalivyotokea." with "Gari lilisimama ghafla, Wanjiru alienda dukani, alivuka barabara bila kuangalia" among the options.', 'Three picture cards of the events; the child lays them left to right and retells with kwanza, kisha, mwishowe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA.M3_SIK_ADD_T5', 'KISW.G3.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA', 'Adds events that were not in the passage when retelling.', '{"question":"Unaposimulia upya, unaongeza mambo ambayo hayakuwa kwenye kifungu?","wrong_answer":"ndiyo, ili hadithi iwe tamu","correct_answer":"hapana, ninasimulia yaliyokuwemo tu"}'::jsonb, 'Retelling is taken as storytelling: the child invents to make it longer.', 'The question "Unaposimulia upya, unaongeza mambo ambayo hayakuwa kwenye kifungu?" with "ndiyo, ili hadithi iwe tamu" among the options.', 'After the retelling, the class checks each event: was it in the passage? Thumbs up or down.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.UFAHAMU.M3_UFM_WORD_T5', 'KISW.G3.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Gives "waya" the meaning of a word that looks or sounds like it.', '{"question":"Soma: \"Hawa aliona waya wa umeme umeanguka karibu na njia. Alikumbuka maneno ya mwalimu: usiguse waya wa umeme. Alimwita baba mara moja.\" Neno \"waya\" lina maana gani?","wrong_answer":"mayai","correct_answer":"uzi wa chuma unaopitisha umeme"}'::jsonb, 'The child matches the word to a known one by its look instead of reading the sentence around it.', 'The question "Soma: "Hawa aliona waya wa umeme umeanguka karibu na njia. Alikumbuka maneno ya mwalimu: usiguse waya wa umeme. Alimwita baba mara moja." Neno "waya" lina maana gani?" with "mayai" among the options.', 'Cover the word; the child says what word would fit the sentence, then uncovers it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.UFAHAMU.M3_UFM_MSG_T5', 'KISW.G3.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Gives one detail of the passage as its message.', '{"question":"Ujumbe wa kifungu ni upi?","wrong_answer":"Hawa alikuwa njiani.","correct_answer":"Tusiguse waya wa umeme; tuwaite watu wazima."}'::jsonb, 'The detail is what the child remembers best; he has not been asked what the writer wants us to know.', 'The question "Ujumbe wa kifungu ni upi?" with "Hawa alikuwa njiani." among the options.', 'Ask two questions side by side: "Nini kilitokea?" and "Kifungu kinatuambia nini?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.UFAHAMU.M3_UFM_GUESS_T5', 'KISW.G3.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Predicts something the passage gives no clue for, without looking at the picture.', '{"question":"Picha inaonyesha baba akipiga simu. Baba atafanya nini?","wrong_answer":"Atashika waya kwa mkono.","correct_answer":"Atawapigia wataalamu wa umeme waje kuurekebisha."}'::jsonb, 'Prediction is taken as free imagination; the child has not been shown that clues in the text and picture point the way.', 'The question "Picha inaonyesha baba akipiga simu. Baba atafanya nini?" with "Atashika waya kwa mkono." among the options.', 'Underline the clue words and point at the picture; the guess must fit them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.UFAHAMU.M3_UFM_LESSON_T5', 'KISW.G3.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Retells what happened when asked for the lesson.', '{"question":"Tunajifunza nini kutokana na kifungu?","wrong_answer":"Hawa aliona waya njiani.","correct_answer":"Tunapaswa kuepuka hatari na kuwaeleza watu wazima."}'::jsonb, 'The lesson question sounds like a what-happened question to the child.', 'The question "Tunajifunza nini kutokana na kifungu?" with "Hawa aliona waya njiani." among the options.', 'Start the answer with "Tunajifunza kwamba tunapaswa..."', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.UFAHAMU.M3_UFM_OWN_T5', 'KISW.G3.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Answers from his own life instead of from the passage.', '{"question":"Hawa alimwita nani?","wrong_answer":"Mimi ningempigia mama simu.","correct_answer":"Baba"}'::jsonb, 'The child links the question to what he knows from home and does not check the text.', 'The question "Hawa alimwita nani?" with "Mimi ningempigia mama simu." among the options.', 'Ask the child to point at the line in the passage that gives the answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T5_MATUMIZI_YA_KIULIZI.ALAMA.M3_ALA_STOPQ_T5', 'KISW.G3.KUANDI.T5_MATUMIZI_YA_KIULIZI.ALAMA', 'Ends a question with a kikomo.', '{"question":"Weka alama sahihi: Unaenda wapi","wrong_answer":"Unaenda wapi.","correct_answer":"Unaenda wapi?"}'::jsonb, 'The child ends every sentence the same way.', 'The question "Weka alama sahihi: Unaenda wapi" with "Unaenda wapi." among the options.', 'Read the sentence aloud: if the voice rises and asks, it takes a kiulizi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T5_MATUMIZI_YA_KIULIZI.ALAMA.M3_ALA_QST_T5', 'KISW.G3.KUANDI.T5_MATUMIZI_YA_KIULIZI.ALAMA', 'Puts a kiulizi after a statement.', '{"question":"Weka alama sahihi: Mimi ninaenda sokoni","wrong_answer":"Mimi ninaenda sokoni?","correct_answer":"Mimi ninaenda sokoni."}'::jsonb, 'The child uses ? as a decoration or thinks any sentence about himself is a question.', 'The question "Weka alama sahihi: Mimi ninaenda sokoni" with "Mimi ninaenda sokoni?" among the options.', 'Ask: does the sentence want an answer? If not, kikomo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T5_MATUMIZI_YA_KIULIZI.ALAMA.M3_ALA_REPORTED_T5', 'KISW.G3.KUANDI.T5_MATUMIZI_YA_KIULIZI.ALAMA', 'Puts a kiulizi after a reported question (Mama aliniuliza ninaenda wapi?).', '{"question":"Weka alama sahihi: Mama aliniuliza ninaenda wapi","wrong_answer":"Mama aliniuliza ninaenda wapi?","correct_answer":"Mama aliniuliza ninaenda wapi."}'::jsonb, 'The question word wapi makes the child think the sentence is a question; it only tells that one was asked.', 'The question "Weka alama sahihi: Mama aliniuliza ninaenda wapi" with "Mama aliniuliza ninaenda wapi?" among the options.', 'Compare "Unaenda wapi?" (asked now) with "Aliniuliza ninaenda wapi." (told).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T5_MATUMIZI_YA_KIULIZI.ALAMA.M3_ALA_MANY_T5', 'KISW.G3.KUANDI.T5_MATUMIZI_YA_KIULIZI.ALAMA', 'Puts several kiulizi (???) for a strong question.', '{"question":"Ni lipi sahihi?","wrong_answer":"Je, tunavuka barabara wapi???","correct_answer":"Je, tunavuka barabara wapi?"}'::jsonb, 'Text messages and cartoons use many marks; the child copies them.', 'The question "Ni lipi sahihi?" with "Je, tunavuka barabara wapi???" among the options.', 'One question, one kiulizi; show a page from the class reader.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T5_MATUMIZI_YA_KIULIZI.ALAMA.M3_ALA_CAP_T5', 'KISW.G3.KUANDI.T5_MATUMIZI_YA_KIULIZI.ALAMA', 'Writes a small letter after a kikomo or kiulizi.', '{"question":"Ni lipi sahihi?","wrong_answer":"Tunavuka barabara kwenye kivuko. mama alifurahi.","correct_answer":"Tunavuka barabara kwenye kivuko. Mama alifurahi."}'::jsonb, 'The child does not link the mark to the capital that follows it.', 'The question "Ni lipi sahihi?" with "Tunavuka barabara kwenye kivuko. mama alifurahi." among the options.', 'Every kikomo is a gate: the next word starts big.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T5_MATUMIZI_YA_AKE_NA_A.VIMILIKISHI.M3_SAR_CONCPOSS_T5', 'KISW.G3.SARUFI.T5_MATUMIZI_YA_AKE_NA_A.VIMILIKISHI', 'Uses the wrong noun-class form of the possessive (kitabu yangu for kitabu changu).', '{"question":"Jaza: Kiti ___ (cha Juma) kimevunjika.","wrong_answer":"yake","correct_answer":"chake"}'::jsonb, 'Town Kiswahili uses yangu, yako, yake for every noun; the child has not seen the ngeli agreement.', 'The question "Jaza: Kiti ___ (cha Juma) kimevunjika." with "yake" among the options.', 'Pair nouns and possessives by colour: kitabu changu, kiti chake, mtoto wangu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T5_MATUMIZI_YA_AKE_NA_A.VIMILIKISHI.M3_SAR_NUMPOSS_T5', 'KISW.G3.SARUFI.T5_MATUMIZI_YA_AKE_NA_A.VIMILIKISHI', 'Leaves the possessive singular with a plural noun (vitabu changu).', '{"question":"Jaza: Viatu ___ (vya Juma) ni vipya.","wrong_answer":"chake","correct_answer":"vyake"}'::jsonb, 'The child changes the noun and forgets the possessive.', 'The question "Jaza: Viatu ___ (vya Juma) ni vipya." with "chake" among the options.', 'Change one object to many in front of the child; both words change.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T5_MATUMIZI_YA_AKE_NA_A.VIMILIKISHI.M3_SAR_OWNER_T5', 'KISW.G3.SARUFI.T5_MATUMIZI_YA_AKE_NA_A.VIMILIKISHI', 'Uses the possessive of the wrong owner (-ake for something that is his own, -ake for many owners).', '{"question":"Watoto wana mpira. Ni mpira ___.","wrong_answer":"wake","correct_answer":"wao"}'::jsonb, 'The child has not linked -angu, -ako, -ake, -etu, -enu, -ao to who owns the thing.', 'The question "Watoto wana mpira. Ni mpira ___." with "wake" among the options.', 'Hold up an object: Ni cha nani? Answer with the owner first, then the possessive.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T5_MATUMIZI_YA_AKE_NA_A.VIMILIKISHI.M3_SAR_ORDERPOSS_T5', 'KISW.G3.SARUFI.T5_MATUMIZI_YA_AKE_NA_A.VIMILIKISHI', 'Puts the possessive before the noun (yangu kalamu), in English word order.', '{"question":"Ni lipi sahihi?","wrong_answer":"yake kofia","correct_answer":"kofia yake"}'::jsonb, 'English puts "my" before the noun; Kiswahili puts it after.', 'The question "Ni lipi sahihi?" with "yake kofia" among the options.', 'Build the phrase with cards: the noun first, then the possessive.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI.M3_SAU_NEAR_T6', 'KISW.G3.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI', 'Says /z/ for /dh/, so "dhahabu" becomes "zahabu".', '{"question":"Mwalimu anasema \"dhahabu\". Neno lipi limetamkwa vizuri?","wrong_answer":"zahabu","correct_answer":"dhahabu"}'::jsonb, 'Many Kenyan first languages have no /dh/, or do not separate it from /z/; the child puts in the home sound.', 'The question "Mwalimu anasema "dhahabu". Neno lipi limetamkwa vizuri?" with "zahabu" among the options.', 'Say the two side by side, slowly, watching the mouth; the child holds up a card for the sound he hears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI.M3_SAU_NEAR2_T6', 'KISW.G3.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI', 'Says /sh/ for /ch/, so "chai" becomes "shai".', '{"question":"Neno lipi limetamkwa vizuri?","wrong_answer":"shai","correct_answer":"chai"}'::jsonb, '/ch/ and /sh/ are close; a first language with only one of them puts that one in both places.', 'The question "Neno lipi limetamkwa vizuri?" with "shai" among the options.', 'Contrast the two with a mirror and a hand before the mouth; the child says which he hears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI.M3_SAU_DROP_T6', 'KISW.G3.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI', 'Drops part of the target sound, so "thelathini" becomes "telatini".', '{"question":"Neno \"thelathini\" limeandikwa au kutamkwa vipi kwa usahihi?","wrong_answer":"telatini","correct_answer":"thelathini"}'::jsonb, 'The second part of the sound (the w or y glide, or the soft nasal) is quick and quiet; the child does not hear it and leaves it out.', 'The question "Neno "thelathini" limeandikwa au kutamkwa vipi kwa usahihi?" with "telatini" among the options.', 'Stretch the syllable slowly (p-y-a), then say it fast; the child copies.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI.M3_SAU_SYLL_T6', 'KISW.G3.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI', 'Splits "dhahabu" by letters rather than by syllables (each Kiswahili syllable ends in a vowel).', '{"question":"Neno \"dhahabu\" lina silabi zipi?","wrong_answer":"d-h-a-h-a-b-u","correct_answer":"dha-ha-bu"}'::jsonb, 'The child has learnt letters one by one and has not been shown that a syllable is a sound that ends in a vowel.', 'The question "Neno "dhahabu" lina silabi zipi?" with "d-h-a-h-a-b-u" among the options.', 'Clap the word: one clap per vowel; the consonants go with the vowel after them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI.M3_SAU_PICK_T6', 'KISW.G3.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI', 'Picks a word with no target sound when asked for one that has it.', '{"question":"Ni neno lipi lina sauti /dh/, /th/, /ch/?","wrong_answer":"mama","correct_answer":"thelathini"}'::jsonb, 'The child looks at the first letter or the picture, not at the sound.', 'The question "Ni neno lipi lina sauti /dh/, /th/, /ch/?" with "mama" among the options.', 'Underline the target sound in each word on the card before choosing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T6_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M3_UFS_SOUND_T6', 'KISW.G3.KUSOMA.T6_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads the target word wrongly: "thamani" as "samani".', '{"question":"Neno \"thamani\" linasomwa vipi?","wrong_answer":"samani","correct_answer":"thamani"}'::jsonb, 'The child reads the letters with the sounds of his first language, or adds a vowel to break the cluster.', 'The question "Neno "thamani" linasomwa vipi?" with "samani" among the options.', 'Pick out the target words before reading; practise them on cards, then read the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T6_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M3_UFS_WORD_T6', 'KISW.G3.KUSOMA.T6_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Tunatupa taka katika pipa la taka.\"?","wrong_answer":"Tunatupa ... taka ... katika ... pipa ... la ... taka.","correct_answer":"Tunatupa taka katika pipa la taka."}'::jsonb, 'The child is still decoding each word; he has not yet read a group of words as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Tunatupa taka katika pipa la taka."?" with "Tunatupa ... taka ... katika ... pipa ... la ... taka." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it in one breath.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T6_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M3_UFS_QUIET_T6', 'KISW.G3.KUSOMA.T6_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads so softly (or so loudly, shouting) that the class cannot follow.', '{"question":"Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?","wrong_answer":"ya chini ili nisikosee mbele ya wenzangu","correct_answer":"ya kusikika na wote darasani, bila kupiga kelele"}'::jsonb, 'Shyness, or the belief that reading well means reading loud.', 'The question "Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?" with "ya chini ili nisikosee mbele ya wenzangu" among the options.', 'Stand the reader at the front and a listener at the back: the listener raises a hand when he hears every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T6_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M3_UFS_PACE_T6', 'KISW.G3.KUSOMA.T6_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Kasi ifaayo ya kusoma kifungu ni ipi?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, karibu maneno 51 kwa dakika"}'::jsonb, 'Reading races in class reward speed; nobody asked whether the listeners understood.', 'The question "Kasi ifaayo ya kusoma kifungu ni ipi?" with "haraka iwezekanavyo" among the options.', 'Time two readings, one very fast and one at speaking pace; the listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T6_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M3_UFS_MARK_T6', 'KISW.G3.KUSOMA.T6_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads a question in the flat voice of a statement and runs on through the koma and kikomo.', '{"question":"Sentensi \"Je, umeokota chupa thelathini?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the marks.', 'The question "Sentensi "Je, umeokota chupa thelathini?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that fits each reading; clap at each kikomo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T6_IMLA.IMLA.M3_TAH_MT_T6', 'KISW.G3.KUANDI.T6_IMLA.IMLA', 'Spells the word with the sound of his first language: "thelathini" written "selasini".', '{"question":"Ni tahajia ipi sahihi?","wrong_answer":"selasini","correct_answer":"thelathini"}'::jsonb, 'The child writes as he says the word; if his first language merges the two sounds, the letter is a guess.', 'The question "Ni tahajia ipi sahihi?" with "selasini" among the options.', 'Keep a list of the class''s hard pairs (l/r, s/sh, z/dh, s/th); say each word slowly before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T6_IMLA.IMLA.M3_TAH_NASAL_T6', 'KISW.G3.KUANDI.T6_IMLA.IMLA', 'Drops the nasal: "ndoo" written "doo".', '{"question":"Ni tahajia ipi sahihi?","wrong_answer":"doo","correct_answer":"ndoo"}'::jsonb, 'The n or m before a consonant is soft and quick; the child does not hear it.', 'The question "Ni tahajia ipi sahihi?" with "doo" among the options.', 'Hum the nasal before the word (mmm-bwa, nnn-dege).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T6_IMLA.IMLA.M3_TAH_VOWEL_T6', 'KISW.G3.KUANDI.T6_IMLA.IMLA', 'Writes a long vowel short, so the word changes: "saa" written "sa".', '{"question":"Andika neno lenye maana ya \"kifaa cha kuonyesha wakati\".","wrong_answer":"sa","correct_answer":"saa"}'::jsonb, 'The child hears the length but does not know it is shown by two letters.', 'The question "Andika neno lenye maana ya "kifaa cha kuonyesha wakati"." with "sa" among the options.', 'Clap the two vowels as two beats; compare a word with one and two vowels.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T6_IMLA.IMLA.M3_TAH_NGAPOS_T6', 'KISW.G3.KUANDI.T6_IMLA.IMLA', 'Writes ng'' without the apostrophe (ngombe for ng''ombe), or puts it where it does not belong (ng''oma for ngoma).', '{"question":"Ni tahajia ipi sahihi ya mnyama anayetupa maziwa?","wrong_answer":"ngombe","correct_answer":"ng''ombe"}'::jsonb, 'Ng'' and ng are two sounds; the apostrophe looks like dirt on the page to the child.', 'The question "Ni tahajia ipi sahihi ya mnyama anayetupa maziwa?" with "ngombe" among the options.', 'Say ng''ombe and ngoma: the first has no g sound; mark it with the apostrophe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T6_IMLA.IMLA.M3_TAH_JOIN_T6', 'KISW.G3.KUANDI.T6_IMLA.IMLA', 'Joins two words into one, or splits one word into two (kwasababu; mwana funzi).', '{"question":"Ni lipi sahihi?","wrong_answer":"Nilichelewa kwasababu ya mvua.","correct_answer":"Nilichelewa kwa sababu ya mvua."}'::jsonb, 'In speech the words run together; the child has not seen each written apart.', 'The question "Ni lipi sahihi?" with "Nilichelewa kwasababu ya mvua." among the options.', 'Count the words aloud with a finger for each before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T6_MATUMIZI_YA_EUPE_EUS.VIVUMISHI.M3_SAR_VOWELADJ_T6', 'KISW.G3.SARUFI.T6_MATUMIZI_YA_EUPE_EUS.VIVUMISHI', 'Writes the colour word without the sound change (kiti kieupe for kiti cheupe; nguo eupe for nguo nyeupe).', '{"question":"Jaza: Kiti ___ (-eupe).","wrong_answer":"kieupe","correct_answer":"cheupe"}'::jsonb, 'The child sticks the prefix on the stem; the sound change when ki- or n- meets the vowel (ki + eupe = cheupe) is new.', 'The question "Jaza: Kiti ___ (-eupe)." with "kieupe" among the options.', 'Say the joined forms slowly: ki-eupe becomes cheupe; n-eupe becomes nyeupe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T6_MATUMIZI_YA_EUPE_EUS.VIVUMISHI.M3_SAR_NADJ_T6', 'KISW.G3.SARUFI.T6_MATUMIZI_YA_EUPE_EUS.VIVUMISHI', 'Gives an n-n noun the m- form of the adjective (nyumba mzuri for nyumba nzuri).', '{"question":"Jaza: Nguo ___ (-eusi).","wrong_answer":"mweusi","correct_answer":"nyeusi"}'::jsonb, 'The n- prefix and its sound changes (nzuri, ndefu, nyeupe) are new to the child.', 'The question "Jaza: Nguo ___ (-eusi)." with "mweusi" among the options.', 'Read pairs aloud: nyumba nzuri, kalamu ndefu, nguo nyeupe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T6_MATUMIZI_YA_EUPE_EUS.VIVUMISHI.M3_SAR_CONCADJ_T6', 'KISW.G3.SARUFI.T6_MATUMIZI_YA_EUPE_EUS.VIVUMISHI', 'Gives the adjective the people prefix whatever the noun (kiti mzuri).', '{"question":"Jaza: Kikombe ___ (-ekundu).","wrong_answer":"mwekundu","correct_answer":"chekundu"}'::jsonb, 'Mzuri is the form the child hears most (mtoto mzuri) and is used everywhere.', 'The question "Jaza: Kikombe ___ (-ekundu)." with "mwekundu" among the options.', 'Match noun and adjective by colour: kiti kizuri, mtoto mzuri, vitu vizuri.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T6_MATUMIZI_YA_EUPE_EUS.VIVUMISHI.M3_SAR_ORDERADJ_T6', 'KISW.G3.SARUFI.T6_MATUMIZI_YA_EUPE_EUS.VIVUMISHI', 'Puts the adjective before the noun (mzuri mtoto), in English word order.', '{"question":"Ni lipi sahihi?","wrong_answer":"nyeupe karatasi","correct_answer":"karatasi nyeupe"}'::jsonb, 'English puts the describing word first.', 'The question "Ni lipi sahihi?" with "nyeupe karatasi" among the options.', 'Build with cards: noun first, then the adjective.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T6_MATUMIZI_YA_EUPE_EUS.VIVUMISHI.M3_SAR_PLADJ_T6', 'KISW.G3.SARUFI.T6_MATUMIZI_YA_EUPE_EUS.VIVUMISHI', 'Leaves the adjective singular with a plural noun (watoto mzuri).', '{"question":"Jaza: Mifuko ___ (-eusi).","wrong_answer":"mweusi","correct_answer":"myeusi"}'::jsonb, 'The child changes the noun only.', 'The question "Jaza: Mifuko ___ (-eusi)." with "mweusi" among the options.', 'Change the noun to many and ask the child to change every word that goes with it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T7_MAAGIZO.MAAGIZO.M3_MAG_HALF_T7', 'KISW.G3.KUSIKI.T7_MAAGIZO.MAAGIZO', 'Carries out only the first part of a two-step instruction.', '{"question":"Agizo: \"Chukua kikapu, kisha uende dukani.\" Umefanya nini?","wrong_answer":"anachukua kikapu tu","correct_answer":"anachukua kikapu kisha anaenda dukani"}'::jsonb, 'The child starts acting as soon as he hears the first verb and stops listening.', 'The question "Agizo: "Chukua kikapu, kisha uende dukani." Umefanya nini?" with "anachukua kikapu tu" among the options.', 'Hold up one finger for each step while giving the instruction; the child repeats the steps before moving.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T7_MAAGIZO.MAAGIZO.M3_MAG_ORDER_T7', 'KISW.G3.KUSIKI.T7_MAAGIZO.MAAGIZO', 'Does the steps in the wrong order.', '{"question":"Agizo: \"Osha mikono, kisha ule chakula.\" Ni nini kinatangulia?","wrong_answer":"kula chakula","correct_answer":"kuosha mikono"}'::jsonb, 'The child does the step he wants most first; the order words kwanza and kisha are not yet noticed.', 'The question "Agizo: "Osha mikono, kisha ule chakula." Ni nini kinatangulia?" with "kula chakula" among the options.', 'Number the steps on the board with kwanza, kisha, mwishowe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T7_MAAGIZO.MAAGIZO.M3_MAG_DIR_T7', 'KISW.G3.KUSIKI.T7_MAAGIZO.MAAGIZO', 'Mixes a direction or action word.', '{"question":"Agizo: \"Weka sukari upande wa kulia wa meza.\" Ni kitendo kipi sahihi?","wrong_answer":"anaiweka upande wa kushoto","correct_answer":"anaiweka upande wa kulia"}'::jsonb, 'Pairs such as kulia/kushoto and juu/chini are learnt together and swapped.', 'The question "Agizo: "Weka sukari upande wa kulia wa meza." Ni kitendo kipi sahihi?" with "anaiweka upande wa kushoto" among the options.', 'Play "Mwalimu anasema": the teacher calls the word, the child acts it; mark the right hand with a band.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T7_MAAGIZO.MAAGIZO.M3_MAG_VAGUE_T7', 'KISW.G3.KUSIKI.T7_MAAGIZO.MAAGIZO', 'Gives an instruction that leaves out what to act on, or with no polite word (Lete!).', '{"question":"Ni agizo lipi liko wazi na lina adabu?","wrong_answer":"Lete!","correct_answer":"Tafadhali lete kitabu chako mezani."}'::jsonb, 'The child knows what he means and does not see that the listener cannot.', 'The question "Ni agizo lipi liko wazi na lina adabu?" with "Lete!" among the options.', 'The child gives the instruction to a partner, who does exactly what was said and no more.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.UFAHAMU.M3_UFM_WORD_T7', 'KISW.G3.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Gives "chenji" the meaning of a word that looks or sounds like it.', '{"question":"Soma: \"Mama alimpa Otieno shilingi mia moja. Otieno alinunua mkate wa shilingi sitini na maziwa ya shilingi thelathini. Muuzaji alimrudishia chenji.\" Neno \"chenji\" lina maana gani?","wrong_answer":"chupa","correct_answer":"pesa zinazorudishwa baada ya kulipa zaidi"}'::jsonb, 'The child matches the word to a known one by its look instead of reading the sentence around it.', 'The question "Soma: "Mama alimpa Otieno shilingi mia moja. Otieno alinunua mkate wa shilingi sitini na maziwa ya shilingi thelathini. Muuzaji alimrudishia chenji." Neno "chenji" lina maana gani?" with "chupa" among the options.', 'Cover the word; the child says what word would fit the sentence, then uncovers it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.UFAHAMU.M3_UFM_MSG_T7', 'KISW.G3.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Gives one detail of the passage as its message.', '{"question":"Ujumbe wa kifungu ni upi?","wrong_answer":"Otieno alinunua mkate.","correct_answer":"Tunapaswa kuhesabu pesa vizuri tunaponunua bidhaa."}'::jsonb, 'The detail is what the child remembers best; he has not been asked what the writer wants us to know.', 'The question "Ujumbe wa kifungu ni upi?" with "Otieno alinunua mkate." among the options.', 'Ask two questions side by side: "Nini kilitokea?" and "Kifungu kinatuambia nini?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.UFAHAMU.M3_UFM_GUESS_T7', 'KISW.G3.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Predicts something the passage gives no clue for.', '{"question":"Otieno atampa mama nini akirudi nyumbani?","wrong_answer":"pipi","correct_answer":"mkate, maziwa na chenji ya shilingi kumi"}'::jsonb, 'Prediction is taken as free imagination; the child has not been shown that clues in the text and picture point the way.', 'The question "Otieno atampa mama nini akirudi nyumbani?" with "pipi" among the options.', 'Underline the clue words; the guess must fit them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.UFAHAMU.M3_UFM_LESSON_T7', 'KISW.G3.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Retells what happened when asked for the lesson.', '{"question":"Tunajifunza nini kutokana na kifungu?","wrong_answer":"Otieno alienda dukani.","correct_answer":"Tuwe waaminifu na tumrudishie mzazi chenji."}'::jsonb, 'The lesson question sounds like a what-happened question to the child.', 'The question "Tunajifunza nini kutokana na kifungu?" with "Otieno alienda dukani." among the options.', 'Start the answer with "Tunajifunza kwamba tunapaswa..."', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.UFAHAMU.M3_UFM_OWN_T7', 'KISW.G3.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Answers from his own life instead of from the passage.', '{"question":"Otieno alipewa shilingi ngapi?","wrong_answer":"Mimi hupewa shilingi hamsini.","correct_answer":"shilingi mia moja"}'::jsonb, 'The child links the question to what he knows from home and does not check the text.', 'The question "Otieno alipewa shilingi ngapi?" with "Mimi hupewa shilingi hamsini." among the options.', 'Ask the child to point at the line in the passage that gives the answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T7_UANDISHI_WA_INSHA.INSHA.M3_INS_LIST_T7', 'KISW.G3.KUANDI.T7_UANDISHI_WA_INSHA.INSHA', 'Writes a list of sentences with no beginning, middle and end.', '{"question":"Kisa kizuri kina sehemu gani?","wrong_answer":"sentensi nyingi tu","correct_answer":"mwanzo, kati na mwisho"}'::jsonb, 'The child thinks length makes a story.', 'The question "Kisa kizuri kina sehemu gani?" with "sentensi nyingi tu" among the options.', 'Plan on three boxes: mwanzo (who, where), kati (what happened), mwisho (how it ended).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T7_UANDISHI_WA_INSHA.INSHA.M3_INS_TITLE_T7', 'KISW.G3.KUANDI.T7_UANDISHI_WA_INSHA.INSHA', 'Writes no title, or a title that does not fit the writing.', '{"question":"Kichwa kipi kinafaa insha kuhusu dukani?","wrong_answer":"Insha","correct_answer":"Siku Nilipoenda Dukani"}'::jsonb, 'The child thinks the word "insha" or the date is the title.', 'The question "Kichwa kipi kinafaa insha kuhusu dukani?" with "Insha" among the options.', 'Read the finished writing and ask: what is it about in three words?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T7_UANDISHI_WA_INSHA.INSHA.M3_INS_HALAFU_T7', 'KISW.G3.KUANDI.T7_UANDISHI_WA_INSHA.INSHA', 'Joins every sentence with "na halafu", so the writing is one long sentence.', '{"question":"Ni lipi limeandikwa vizuri?","wrong_answer":"Tuliamka na halafu tukaoga na halafu tukaenda sokoni.","correct_answer":"Tuliamka asubuhi. Tulioga, kisha tukaenda sokoni."}'::jsonb, 'Spoken retelling joins events with na halafu; the child writes as he talks.', 'The question "Ni lipi limeandikwa vizuri?" with "Tuliamka na halafu tukaoga na halafu tukaenda sokoni." among the options.', 'Give a word bank: kwanza, kisha, baadaye, mwishowe; one per sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T7_UANDISHI_WA_INSHA.INSHA.M3_INS_TENSE_T7', 'KISW.G3.KUANDI.T7_UANDISHI_WA_INSHA.INSHA', 'Slips from one tense to another in the middle of the writing (past -li- to present -na-, or habitual hu- to past).', '{"question":"Ni lipi sahihi?","wrong_answer":"Jana nilienda dukani. Ninanunua sukari.","correct_answer":"Jana nilienda dukani. Nilinunua sukari."}'::jsonb, 'The child thinks of the events as he writes and the tense of the moment comes in.', 'The question "Ni lipi sahihi?" with "Jana nilienda dukani. Ninanunua sukari." among the options.', 'Underline every verb; all the tense markers should match.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T7_UANDISHI_WA_INSHA.INSHA.M3_INS_MIX_T7', 'KISW.G3.KUANDI.T7_UANDISHI_WA_INSHA.INSHA', 'Puts English or Sheng words into the Kiswahili writing.', '{"question":"Sahihisha:","wrong_answer":"Nilinunua sugar na bread.","correct_answer":"Nilinunua sukari na mkate."}'::jsonb, 'The child does not know the Kiswahili word and fills the gap with the one he knows.', 'The question "Sahihisha:" with "Nilinunua sugar na bread." among the options.', 'Keep a word bank of theme words on the board before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T7_UKANUSHAJI_WA_NAFSI_.UKANUSHAJI.M3_SAR_FINALA_T7', 'KISW.G3.SARUFI.T7_UKANUSHAJI_WA_NAFSI_.UKANUSHAJI', 'Keeps the final -a in the negative present (hasoma for hasomi).', '{"question":"Kanusha: Yeye anauza sukari.","wrong_answer":"Yeye hauza sukari.","correct_answer":"Yeye hauzi sukari."}'::jsonb, 'The child adds the negative prefix and leaves the rest of the verb as it was.', 'The question "Kanusha: Yeye anauza sukari." with "Yeye hauza sukari." among the options.', 'Show the pair with the end of the verb circled: anasoma - hasomi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T7_UKANUSHAJI_WA_NAFSI_.UKANUSHAJI.M3_SAR_KEEPNA_T7', 'KISW.G3.SARUFI.T7_UKANUSHAJI_WA_NAFSI_.UKANUSHAJI', 'Keeps the tense marker -na- in the negative (hanasomi for hasomi).', '{"question":"Kanusha: Yeye ananunua mkate.","wrong_answer":"Yeye hananunui mkate.","correct_answer":"Yeye hanunui mkate."}'::jsonb, 'The child negates by adding ha- to the whole positive verb.', 'The question "Kanusha: Yeye ananunua mkate." with "Yeye hananunui mkate." among the options.', 'Cross out na in the positive form and change the end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T7_UKANUSHAJI_WA_NAFSI_.UKANUSHAJI.M3_SAR_SIPLUS_T7', 'KISW.G3.SARUFI.T7_UKANUSHAJI_WA_NAFSI_.UKANUSHAJI', 'Negates by putting si before the positive verb (Yeye si anasoma).', '{"question":"Kanusha: Muuzaji anafungua duka.","wrong_answer":"Muuzaji si anafungua duka.","correct_answer":"Muuzaji hafungui duka."}'::jsonb, 'Si is the negative the child knows (si mimi), so he puts it in front of any sentence.', 'The question "Kanusha: Muuzaji anafungua duka." with "Muuzaji si anafungua duka." among the options.', 'Show si as the negative of ni (Yeye si mwalimu) and ha- as the negative of a verb.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T7_UKANUSHAJI_WA_NAFSI_.UKANUSHAJI.M3_SAR_PERSNEG_T7', 'KISW.G3.SARUFI.T7_UKANUSHAJI_WA_NAFSI_.UKANUSHAJI', 'Uses the negative prefix of another person (Wao hasomi for hawasomi; Mimi hasomi for sisomi).', '{"question":"Kanusha: Wao wanauza maziwa.","wrong_answer":"Wao hauzi maziwa.","correct_answer":"Wao hawauzi maziwa."}'::jsonb, 'The child learnt one negative form (ha-) and uses it for all persons.', 'The question "Kanusha: Wao wanauza maziwa." with "Wao hauzi maziwa." among the options.', 'Table of persons: si-, hu-, ha-, hatu-, ham-, hawa-; the child points before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI.M3_SAU_NEAR_T8', 'KISW.G3.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI', 'Says /n/ for /ny/, so "nyama" becomes "nama".', '{"question":"Mwalimu anasema \"nyama\". Neno lipi limetamkwa vizuri?","wrong_answer":"nama","correct_answer":"nyama"}'::jsonb, 'Many Kenyan first languages have no /ny/, or do not separate it from /n/; the child puts in the home sound.', 'The question "Mwalimu anasema "nyama". Neno lipi limetamkwa vizuri?" with "nama" among the options.', 'Say the two side by side, slowly, watching the mouth; the child holds up a card for the sound he hears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI.M3_SAU_VOWEL_T8', 'KISW.G3.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI', 'Pushes a vowel into the cluster, so "mbwa" is said "mubwa".', '{"question":"Tamka neno \"mbwa\". Ni lipi sahihi?","wrong_answer":"mubwa","correct_answer":"mbwa"}'::jsonb, 'In the child''s first language, or in English loan habits, two consonants rarely sit together; he breaks them with a vowel.', 'The question "Tamka neno "mbwa". Ni lipi sahihi?" with "mubwa" among the options.', 'Say the cluster in one beat, then the word; clap once for the cluster syllable.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI.M3_SAU_DROP_T8', 'KISW.G3.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI', 'Drops part of the target sound, so "ndege" becomes "dege".', '{"question":"Neno \"ndege\" limeandikwa au kutamkwa vipi kwa usahihi?","wrong_answer":"dege","correct_answer":"ndege"}'::jsonb, 'The second part of the sound (the w or y glide, or the soft nasal) is quick and quiet; the child does not hear it and leaves it out.', 'The question "Neno "ndege" limeandikwa au kutamkwa vipi kwa usahihi?" with "dege" among the options.', 'Stretch the syllable slowly (p-y-a), then say it fast; the child copies.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI.M3_SAU_SYLL_T8', 'KISW.G3.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI', 'Splits "mbweha" by letters rather than by syllables (each Kiswahili syllable ends in a vowel).', '{"question":"Neno \"mbweha\" lina silabi zipi?","wrong_answer":"m-b-w-e-h-a","correct_answer":"mbwe-ha"}'::jsonb, 'The child has learnt letters one by one and has not been shown that a syllable is a sound that ends in a vowel.', 'The question "Neno "mbweha" lina silabi zipi?" with "m-b-w-e-h-a" among the options.', 'Clap the word: one clap per vowel; the consonants go with the vowel after them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI.M3_SAU_PICK_T8', 'KISW.G3.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI', 'Picks a word with no target sound when asked for one that has it.', '{"question":"Ni neno lipi lina sauti /mbw/, /nd/, /ny/?","wrong_answer":"kuku","correct_answer":"ndege"}'::jsonb, 'The child looks at the first letter or the picture, not at the sound.', 'The question "Ni neno lipi lina sauti /mbw/, /nd/, /ny/?" with "kuku" among the options.', 'Underline the target sound in each word on the card before choosing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M3_UFS_SOUND_T8', 'KISW.G3.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads the target word wrongly: "nyumbani" as "numbani".', '{"question":"Neno \"nyumbani\" linasomwa vipi?","wrong_answer":"numbani","correct_answer":"nyumbani"}'::jsonb, 'The child reads the letters with the sounds of his first language, or adds a vowel to break the cluster.', 'The question "Neno "nyumbani" linasomwa vipi?" with "numbani" among the options.', 'Pick out the target words before reading; practise them on cards, then read the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M3_UFS_WORD_T8', 'KISW.G3.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Ndege wangu anaimba asubuhi.\"?","wrong_answer":"Ndege ... wangu ... anaimba ... asubuhi.","correct_answer":"Ndege wangu anaimba asubuhi."}'::jsonb, 'The child is still decoding each word; he has not yet read a group of words as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Ndege wangu anaimba asubuhi."?" with "Ndege ... wangu ... anaimba ... asubuhi." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it in one breath.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M3_UFS_QUIET_T8', 'KISW.G3.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads so softly (or so loudly, shouting) that the class cannot follow.', '{"question":"Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?","wrong_answer":"ya chini ili nisikosee mbele ya wenzangu","correct_answer":"ya kusikika na wote darasani, bila kupiga kelele"}'::jsonb, 'Shyness, or the belief that reading well means reading loud.', 'The question "Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?" with "ya chini ili nisikosee mbele ya wenzangu" among the options.', 'Stand the reader at the front and a listener at the back: the listener raises a hand when he hears every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M3_UFS_PACE_T8', 'KISW.G3.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Kasi ifaayo ya kusoma kifungu ni ipi?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, karibu maneno 53 kwa dakika"}'::jsonb, 'Reading races in class reward speed; nobody asked whether the listeners understood.', 'The question "Kasi ifaayo ya kusoma kifungu ni ipi?" with "haraka iwezekanavyo" among the options.', 'Time two readings, one very fast and one at speaking pace; the listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M3_UFS_MARK_T8', 'KISW.G3.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads a question in the flat voice of a statement and runs on through the koma and kikomo.', '{"question":"Sentensi \"Je, umemwona mbwa wa jirani?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the marks.', 'The question "Sentensi "Je, umemwona mbwa wa jirani?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that fits each reading; clap at each kikomo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T8_TAHAJIA.TAHAJIA.M3_TAH_MT_T8', 'KISW.G3.KUANDI.T8_TAHAJIA.TAHAJIA', 'Spells the word with the sound of his first language: "rangi" written "langi".', '{"question":"Ni tahajia ipi sahihi?","wrong_answer":"langi","correct_answer":"rangi"}'::jsonb, 'The child writes as he says the word; if his first language merges the two sounds, the letter is a guess.', 'The question "Ni tahajia ipi sahihi?" with "langi" among the options.', 'Keep a list of the class''s hard pairs (l/r, s/sh, z/dh, s/th); say each word slowly before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T8_TAHAJIA.TAHAJIA.M3_TAH_NASAL_T8', 'KISW.G3.KUANDI.T8_TAHAJIA.TAHAJIA', 'Drops the nasal: "mbawa" written "bawa".', '{"question":"Ni tahajia ipi sahihi?","wrong_answer":"bawa","correct_answer":"mbawa"}'::jsonb, 'The n or m before a consonant is soft and quick; the child does not hear it.', 'The question "Ni tahajia ipi sahihi?" with "bawa" among the options.', 'Hum the nasal before the word (mmm-bwa, nnn-dege).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T8_TAHAJIA.TAHAJIA.M3_TAH_VOWEL_T8', 'KISW.G3.KUANDI.T8_TAHAJIA.TAHAJIA', 'Writes a long vowel short, so the word changes: "paa" written "pa".', '{"question":"Andika neno lenye maana ya \"sehemu ya juu ya nyumba\".","wrong_answer":"pa","correct_answer":"paa"}'::jsonb, 'The child hears the length but does not know it is shown by two letters.', 'The question "Andika neno lenye maana ya "sehemu ya juu ya nyumba"." with "pa" among the options.', 'Clap the two vowels as two beats; compare a word with one and two vowels.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T8_TAHAJIA.TAHAJIA.M3_TAH_NGAPOS_T8', 'KISW.G3.KUANDI.T8_TAHAJIA.TAHAJIA', 'Writes ng'' without the apostrophe (ngombe for ng''ombe), or puts it where it does not belong (ng''oma for ngoma).', '{"question":"Ni tahajia ipi sahihi ya mnyama anayetupa maziwa?","wrong_answer":"ngombe","correct_answer":"ng''ombe"}'::jsonb, 'Ng'' and ng are two sounds; the apostrophe looks like dirt on the page to the child.', 'The question "Ni tahajia ipi sahihi ya mnyama anayetupa maziwa?" with "ngombe" among the options.', 'Say ng''ombe and ngoma: the first has no g sound; mark it with the apostrophe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T8_TAHAJIA.TAHAJIA.M3_TAH_JOIN_T8', 'KISW.G3.KUANDI.T8_TAHAJIA.TAHAJIA', 'Joins two words into one, or splits one word into two (kwasababu; mwana funzi).', '{"question":"Ni lipi sahihi?","wrong_answer":"Nilichelewa kwasababu ya mvua.","correct_answer":"Nilichelewa kwa sababu ya mvua."}'::jsonb, 'In speech the words run together; the child has not seen each written apart.', 'The question "Ni lipi sahihi?" with "Nilichelewa kwasababu ya mvua." among the options.', 'Count the words aloud with a finger for each before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T8_MATUMIZI_YA_MANENO_H.VIONYESHI.M3_SAR_CLASSDEM_T8', 'KISW.G3.SARUFI.T8_MATUMIZI_YA_MANENO_H.VIONYESHI', 'Uses the people word (huyu, yule) for a thing (kiti huyu).', '{"question":"Jaza: Yai ___ ni bovu.","wrong_answer":"huyu","correct_answer":"hili"}'::jsonb, 'Huyu was the first pointing word learnt; the child uses it for anything.', 'The question "Jaza: Yai ___ ni bovu." with "huyu" among the options.', 'Point at a child (huyu) and at a chair (hiki); then sort pictures by the pointing word they take.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T8_MATUMIZI_YA_MANENO_H.VIONYESHI.M3_SAR_NUMDEM_T8', 'KISW.G3.SARUFI.T8_MATUMIZI_YA_MANENO_H.VIONYESHI', 'Uses the one-thing pointing word with a plural noun (watoto huyu).', '{"question":"Jaza: Mayai ___ ni mabovu.","wrong_answer":"hili","correct_answer":"haya"}'::jsonb, 'The child changes the noun but not the pointing word.', 'The question "Jaza: Mayai ___ ni mabovu." with "hili" among the options.', 'Pair the forms on cards: huyu-hawa, yule-wale, hiki-hivi, hili-haya.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T8_MATUMIZI_YA_MANENO_H.VIONYESHI.M3_SAR_NCLASS_T8', 'KISW.G3.SARUFI.T8_MATUMIZI_YA_MANENO_H.VIONYESHI', 'Gives a noun of the n-n class a plural prefix (nyumba -> manyumba), or changes an irregular noun wrongly (jicho -> majicho).', '{"question":"Wingi wa \"jicho hili\" ni?","wrong_answer":"majicho haya","correct_answer":"macho haya"}'::jsonb, 'The child expects every plural to look different; n-n nouns stay the same and some li-ma nouns change their stem.', 'The question "Wingi wa "jicho hili" ni?" with "majicho haya" among the options.', 'Keep a short list of the same-in-both nouns (nyumba, ndizi, kalamu) and the irregular ones (jicho - macho, jino - meno).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T8_MATUMIZI_YA_MANENO_H.VIONYESHI.M3_SAR_HII_T8', 'KISW.G3.SARUFI.T8_MATUMIZI_YA_MANENO_H.VIONYESHI', 'Uses hii for every noun (kitabu hii, mtoto hii), as in town Kiswahili.', '{"question":"Jaza: Jani ___ ni la kijani.","wrong_answer":"hii","correct_answer":"hili"}'::jsonb, 'Hii is the pointing word heard most in town speech, where the noun class is dropped.', 'The question "Jaza: Jani ___ ni la kijani." with "hii" among the options.', 'Read pairs aloud: kitabu hiki, mtoto huyu, nyumba hii; the child hears the match.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T9_MAZUNGUMZO.MAZUNGUMZO.M3_MAZ_TOPIC_T9', 'KISW.G3.KUSIKI.T9_MAZUNGUMZO.MAZUNGUMZO', 'Says something that has nothing to do with the topic.', '{"question":"Mnazungumza kuhusu bidhaa za sokoni. Ni sentensi ipi inafaa?","wrong_answer":"Jana nilitazama katuni nzuri.","correct_answer":"Tulienda sokoni tukanunua nyanya."}'::jsonb, 'The child says what is on his mind; he has not learnt that a conversation has a topic everyone keeps to.', 'The question "Mnazungumza kuhusu bidhaa za sokoni. Ni sentensi ipi inafaa?" with "Jana nilitazama katuni nzuri." among the options.', 'Put the topic picture in the middle; before speaking the child points to it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T9_MAZUNGUMZO.MAZUNGUMZO.M3_MAZ_TURN_T9', 'KISW.G3.KUSIKI.T9_MAZUNGUMZO.MAZUNGUMZO', 'Talks over others and does not wait for his turn.', '{"question":"Mwenzako anazungumza. Unafanya nini?","wrong_answer":"ninaanza kuzungumza pia","correct_answer":"ninasikiliza mpaka amalize, kisha ninazungumza"}'::jsonb, 'Eagerness: the child fears he will forget his idea.', 'The question "Mwenzako anazungumza. Unafanya nini?" with "ninaanza kuzungumza pia" among the options.', 'Pass a talking object (a ball): only the one holding it speaks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T9_MAZUNGUMZO.MAZUNGUMZO.M3_MAZ_MIX_T9', 'KISW.G3.KUSIKI.T9_MAZUNGUMZO.MAZUNGUMZO', 'Mixes English or Sheng words into the Kiswahili sentence.', '{"question":"Sema kwa Kiswahili sanifu:","wrong_answer":"Tulienda market tukabuy tomatoes.","correct_answer":"Tulienda sokoni tukanunua nyanya."}'::jsonb, 'At home and in town the child hears mixed speech and does not know the Kiswahili word.', 'The question "Sema kwa Kiswahili sanifu:" with "Tulienda market tukabuy tomatoes." among the options.', 'Keep a word wall: the English or Sheng word, and its Kiswahili word next to it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T9_MAZUNGUMZO.MAZUNGUMZO.M3_MAZ_GEST_T9', 'KISW.G3.KUSIKI.T9_MAZUNGUMZO.MAZUNGUMZO', 'Uses a gesture or face that does not match the words (smiling while giving sad news).', '{"question":"Unasema \"Rafiki yangu ni mgonjwa.\" Uso wako unaonyesha nini?","wrong_answer":"tabasamu kubwa","correct_answer":"huzuni"}'::jsonb, 'The child smiles from shyness or does not link the face to the message.', 'The question "Unasema "Rafiki yangu ni mgonjwa." Uso wako unaonyesha nini?" with "tabasamu kubwa" among the options.', 'Say one sentence with three faces; the class picks the face that fits.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T9_MAZUNGUMZO.MAZUNGUMZO.M3_MAZ_LR_T9', 'KISW.G3.KUSIKI.T9_MAZUNGUMZO.MAZUNGUMZO', 'Says /l/ for /r/ (or /r/ for /l/) while speaking: "rafiki" becomes "lafiki".', '{"question":"Tamka vizuri: rafiki","wrong_answer":"lafiki","correct_answer":"rafiki"}'::jsonb, 'Several Kenyan first languages do not separate /l/ and /r/; the home sound carries into Kiswahili.', 'The question "Tamka vizuri: rafiki" with "lafiki" among the options.', 'Practise the pairs with a mirror: the tongue taps for r, it rests for l.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU.M3_UFM_WORD_T9', 'KISW.G3.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Gives "wateja" the meaning of a word that looks or sounds like it.', '{"question":"Soma: \"Bi. Neema huuza matunda sokoni. Ana maembe, machungwa na mananasi. Wateja wengi hununua matunda yake kwa sababu ni safi na matamu.\" Neno \"wateja\" lina maana gani?","wrong_answer":"watoto","correct_answer":"watu wanaonunua bidhaa"}'::jsonb, 'The child matches the word to a known one by its look instead of reading the sentence around it.', 'The question "Soma: "Bi. Neema huuza matunda sokoni. Ana maembe, machungwa na mananasi. Wateja wengi hununua matunda yake kwa sababu ni safi na matamu." Neno "wateja" lina maana gani?" with "watoto" among the options.', 'Cover the word; the child says what word would fit the sentence, then uncovers it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU.M3_UFM_MSG_T9', 'KISW.G3.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Gives one detail of the passage as its message.', '{"question":"Ujumbe wa kifungu ni upi?","wrong_answer":"Bi. Neema ana maembe.","correct_answer":"Tukiuza bidhaa safi tunapata wateja wengi."}'::jsonb, 'The detail is what the child remembers best; he has not been asked what the writer wants us to know.', 'The question "Ujumbe wa kifungu ni upi?" with "Bi. Neema ana maembe." among the options.', 'Ask two questions side by side: "Nini kilitokea?" and "Kifungu kinatuambia nini?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU.M3_UFM_GUESS_T9', 'KISW.G3.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Predicts something the passage gives no clue for, without looking at the picture.', '{"question":"Picha inaonyesha mawingu meusi juu ya soko. Nini kitatokea?","wrong_answer":"Jua kali litawaka.","correct_answer":"Mvua itanyesha na wauzaji watafunika bidhaa zao."}'::jsonb, 'Prediction is taken as free imagination; the child has not been shown that clues in the text and picture point the way.', 'The question "Picha inaonyesha mawingu meusi juu ya soko. Nini kitatokea?" with "Jua kali litawaka." among the options.', 'Underline the clue words and point at the picture; the guess must fit them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU.M3_UFM_LESSON_T9', 'KISW.G3.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Retells what happened when asked for the lesson.', '{"question":"Tunajifunza nini kutokana na kifungu?","wrong_answer":"Bi. Neema huuza matunda.","correct_answer":"Tunapaswa kuwa safi na waaminifu katika kazi zetu."}'::jsonb, 'The lesson question sounds like a what-happened question to the child.', 'The question "Tunajifunza nini kutokana na kifungu?" with "Bi. Neema huuza matunda." among the options.', 'Start the answer with "Tunajifunza kwamba tunapaswa..."', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU.M3_UFM_OWN_T9', 'KISW.G3.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Answers from his own life instead of from the passage.', '{"question":"Bi. Neema huuza nini?","wrong_answer":"Mama yangu huuza sukumawiki.","correct_answer":"matunda"}'::jsonb, 'The child links the question to what he knows from home and does not check the text.', 'The question "Bi. Neema huuza nini?" with "Mama yangu huuza sukumawiki." among the options.', 'Ask the child to point at the line in the passage that gives the answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T9_INSHA_YA_MASIMULIZI.INSHA.M3_INS_LIST_T9', 'KISW.G3.KUANDI.T9_INSHA_YA_MASIMULIZI.INSHA', 'Writes a list of sentences with no beginning, middle and end.', '{"question":"Kisa kizuri kina sehemu gani?","wrong_answer":"sentensi nyingi tu","correct_answer":"mwanzo, kati na mwisho"}'::jsonb, 'The child thinks length makes a story.', 'The question "Kisa kizuri kina sehemu gani?" with "sentensi nyingi tu" among the options.', 'Plan on three boxes: mwanzo (who, where), kati (what happened), mwisho (how it ended).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T9_INSHA_YA_MASIMULIZI.INSHA.M3_INS_TITLE_T9', 'KISW.G3.KUANDI.T9_INSHA_YA_MASIMULIZI.INSHA', 'Writes no title, or a title that does not fit the writing.', '{"question":"Kichwa kipi kinafaa insha kuhusu sokoni?","wrong_answer":"Insha","correct_answer":"Safari Yangu ya Sokoni"}'::jsonb, 'The child thinks the word "insha" or the date is the title.', 'The question "Kichwa kipi kinafaa insha kuhusu sokoni?" with "Insha" among the options.', 'Read the finished writing and ask: what is it about in three words?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T9_INSHA_YA_MASIMULIZI.INSHA.M3_INS_HALAFU_T9', 'KISW.G3.KUANDI.T9_INSHA_YA_MASIMULIZI.INSHA', 'Joins every sentence with "na halafu", so the writing is one long sentence.', '{"question":"Ni lipi limeandikwa vizuri?","wrong_answer":"Tuliamka na halafu tukaoga na halafu tukaenda sokoni.","correct_answer":"Tuliamka asubuhi. Tulioga, kisha tukaenda sokoni."}'::jsonb, 'Spoken retelling joins events with na halafu; the child writes as he talks.', 'The question "Ni lipi limeandikwa vizuri?" with "Tuliamka na halafu tukaoga na halafu tukaenda sokoni." among the options.', 'Give a word bank: kwanza, kisha, baadaye, mwishowe; one per sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T9_INSHA_YA_MASIMULIZI.INSHA.M3_INS_TENSE_T9', 'KISW.G3.KUANDI.T9_INSHA_YA_MASIMULIZI.INSHA', 'Slips from one tense to another in the middle of the writing (past -li- to present -na-, or habitual hu- to past).', '{"question":"Ni lipi sahihi?","wrong_answer":"Tulifika sokoni mapema. Mama ananunua ndizi.","correct_answer":"Tulifika sokoni mapema. Mama alinunua ndizi."}'::jsonb, 'The child thinks of the events as he writes and the tense of the moment comes in.', 'The question "Ni lipi sahihi?" with "Tulifika sokoni mapema. Mama ananunua ndizi." among the options.', 'Underline every verb; all the tense markers should match.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T9_INSHA_YA_MASIMULIZI.INSHA.M3_INS_MIX_T9', 'KISW.G3.KUANDI.T9_INSHA_YA_MASIMULIZI.INSHA', 'Puts English or Sheng words into the Kiswahili writing.', '{"question":"Sahihisha:","wrong_answer":"Tulinunua sukuma na onions.","correct_answer":"Tulinunua sukumawiki na vitunguu."}'::jsonb, 'The child does not know the Kiswahili word and fills the gap with the one he knows.', 'The question "Sahihisha:" with "Tulinunua sukuma na onions." among the options.', 'Keep a word bank of theme words on the board before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T9_YA_JUU_YA.VIHUSISHI.M3_SAR_DROPYA_T9', 'KISW.G3.SARUFI.T9_YA_JUU_YA.VIHUSISHI', 'Leaves out ya (juu meza for juu ya meza).', '{"question":"Ni lipi sahihi?","wrong_answer":"Ndizi ziko juu meza.","correct_answer":"Ndizi ziko juu ya meza."}'::jsonb, 'In fast speech ya is quick and the child does not hear it.', 'The question "Ni lipi sahihi?" with "Ndizi ziko juu meza." among the options.', 'Say the phrase slowly with a clap on ya.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T9_YA_JUU_YA.VIHUSISHI.M3_SAR_KWA_T9', 'KISW.G3.SARUFI.T9_YA_JUU_YA.VIHUSISHI', 'Uses kwa in place of ya (ndani kwa sanduku).', '{"question":"Ni lipi sahihi?","wrong_answer":"Machungwa yako ndani kwa kikapu.","correct_answer":"Machungwa yako ndani ya kikapu."}'::jsonb, 'Kwa is a common joining word and the child reaches for it.', 'The question "Ni lipi sahihi?" with "Machungwa yako ndani kwa kikapu." among the options.', 'Pair cards: juu ya, ndani ya, mbele ya; kwa is not among them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T9_YA_JUU_YA.VIHUSISHI.M3_SAR_SWAPPOS_T9', 'KISW.G3.SARUFI.T9_YA_JUU_YA.VIHUSISHI', 'Mixes the place words (juu ya for chini ya, mbele ya for nyuma ya).', '{"question":"Muuzaji amesimama mbele ya kibanda. Yuko wapi?","wrong_answer":"nyuma ya kibanda","correct_answer":"mbele ya kibanda"}'::jsonb, 'The pairs are learnt together and swapped.', 'The question "Muuzaji amesimama mbele ya kibanda. Yuko wapi?" with "nyuma ya kibanda" among the options.', 'Place a real ball on, under, in, in front of a box; the child says where.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T9_YA_JUU_YA.VIHUSISHI.M3_SAR_DOUBLENI_T9', 'KISW.G3.SARUFI.T9_YA_JUU_YA.VIHUSISHI', 'Adds -ni to the noun as well as ndani ya (ndani ya sandukuni).', '{"question":"Ni lipi sahihi?","wrong_answer":"Pesa ziko ndani ya mfukoni.","correct_answer":"Pesa ziko ndani ya mfuko."}'::jsonb, 'Both ways of saying "in" are known; the child uses both at once.', 'The question "Ni lipi sahihi?" with "Pesa ziko ndani ya mfukoni." among the options.', 'Show the two ways side by side: sandukuni, or ndani ya sanduku; never both.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI.M3_SAU_NEAR_T10', 'KISW.G3.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI', 'Says /ns/ for /nz/, so "nzuri" becomes "nsuri".', '{"question":"Mwalimu anasema \"nzuri\". Neno lipi limetamkwa vizuri?","wrong_answer":"nsuri","correct_answer":"nzuri"}'::jsonb, 'Many Kenyan first languages have no /nz/, or do not separate it from /ns/; the child puts in the home sound.', 'The question "Mwalimu anasema "nzuri". Neno lipi limetamkwa vizuri?" with "nsuri" among the options.', 'Say the two side by side, slowly, watching the mouth; the child holds up a card for the sound he hears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI.M3_SAU_VOWEL_T10', 'KISW.G3.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI', 'Pushes a vowel into the cluster, so "twiga" is said "tuwiga".', '{"question":"Tamka neno \"twiga\". Ni lipi sahihi?","wrong_answer":"tuwiga","correct_answer":"twiga"}'::jsonb, 'In the child''s first language, or in English loan habits, two consonants rarely sit together; he breaks them with a vowel.', 'The question "Tamka neno "twiga". Ni lipi sahihi?" with "tuwiga" among the options.', 'Say the cluster in one beat, then the word; clap once for the cluster syllable.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI.M3_SAU_DROP_T10', 'KISW.G3.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI', 'Drops part of the target sound, so "mbali" becomes "bali".', '{"question":"Neno \"mbali\" limeandikwa au kutamkwa vipi kwa usahihi?","wrong_answer":"bali","correct_answer":"mbali"}'::jsonb, 'The second part of the sound (the w or y glide, or the soft nasal) is quick and quiet; the child does not hear it and leaves it out.', 'The question "Neno "mbali" limeandikwa au kutamkwa vipi kwa usahihi?" with "bali" among the options.', 'Stretch the syllable slowly (p-y-a), then say it fast; the child copies.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI.M3_SAU_SYLL_T10', 'KISW.G3.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI', 'Splits "mbali" by letters rather than by syllables (each Kiswahili syllable ends in a vowel).', '{"question":"Neno \"mbali\" lina silabi zipi?","wrong_answer":"m-b-a-l-i","correct_answer":"mba-li"}'::jsonb, 'The child has learnt letters one by one and has not been shown that a syllable is a sound that ends in a vowel.', 'The question "Neno "mbali" lina silabi zipi?" with "m-b-a-l-i" among the options.', 'Clap the word: one clap per vowel; the consonants go with the vowel after them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI.M3_SAU_PICK_T10', 'KISW.G3.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI', 'Picks a word with no target sound when asked for one that has it.', '{"question":"Ni neno lipi lina sauti /mb/, /nz/, /tw/?","wrong_answer":"redio","correct_answer":"nzuri"}'::jsonb, 'The child looks at the first letter or the picture, not at the sound.', 'The question "Ni neno lipi lina sauti /mb/, /nz/, /tw/?" with "redio" among the options.', 'Underline the target sound in each word on the card before choosing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M3_UFS_SOUND_T10', 'KISW.G3.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads the target word wrongly: "twende" as "tuwende".', '{"question":"Neno \"twende\" linasomwa vipi?","wrong_answer":"tuwende","correct_answer":"twende"}'::jsonb, 'The child reads the letters with the sounds of his first language, or adds a vowel to break the cluster.', 'The question "Neno "twende" linasomwa vipi?" with "tuwende" among the options.', 'Pick out the target words before reading; practise them on cards, then read the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M3_UFS_WORD_T10', 'KISW.G3.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Mama ana simu mpya ya kisasa.\"?","wrong_answer":"Mama ... ana ... simu ... mpya ... ya ... kisasa.","correct_answer":"Mama ana simu mpya ya kisasa."}'::jsonb, 'The child is still decoding each word; he has not yet read a group of words as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Mama ana simu mpya ya kisasa."?" with "Mama ... ana ... simu ... mpya ... ya ... kisasa." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it in one breath.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M3_UFS_QUIET_T10', 'KISW.G3.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads so softly (or so loudly, shouting) that the class cannot follow.', '{"question":"Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?","wrong_answer":"ya chini ili nisikosee mbele ya wenzangu","correct_answer":"ya kusikika na wote darasani, bila kupiga kelele"}'::jsonb, 'Shyness, or the belief that reading well means reading loud.', 'The question "Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?" with "ya chini ili nisikosee mbele ya wenzangu" among the options.', 'Stand the reader at the front and a listener at the back: the listener raises a hand when he hears every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M3_UFS_PACE_T10', 'KISW.G3.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Kasi ifaayo ya kusoma kifungu ni ipi?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, karibu maneno 55 kwa dakika"}'::jsonb, 'Reading races in class reward speed; nobody asked whether the listeners understood.', 'The question "Kasi ifaayo ya kusoma kifungu ni ipi?" with "haraka iwezekanavyo" among the options.', 'Time two readings, one very fast and one at speaking pace; the listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M3_UFS_MARK_T10', 'KISW.G3.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads a question in the flat voice of a statement and runs on through the koma and kikomo.', '{"question":"Sentensi \"Je, simu hii ni nzuri?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the marks.', 'The question "Sentensi "Je, simu hii ni nzuri?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that fits each reading; clap at each kikomo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T10_INSHA_YA_MAELEZO.INSHA.M3_INS_STORY_T10', 'KISW.G3.KUANDI.T10_INSHA_YA_MAELEZO.INSHA', 'Tells a story of events instead of describing the thing (what it is, what it looks like, what it is for).', '{"question":"Insha ya maelezo kuhusu \"Simu\" inaanza vipi?","wrong_answer":"Siku moja nilienda mjini...","correct_answer":"Simu ni kitu ambacho..."}'::jsonb, 'Every insha the child has written before was a story.', 'The question "Insha ya maelezo kuhusu "Simu" inaanza vipi?" with "Siku moja nilienda mjini..." among the options.', 'Give three question cards: Ni nini? Kinaonekanaje? Kinatumiwaje? One aya each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T10_INSHA_YA_MAELEZO.INSHA.M3_INS_TITLE_T10', 'KISW.G3.KUANDI.T10_INSHA_YA_MAELEZO.INSHA', 'Writes no title, or a title that does not fit the writing.', '{"question":"Kichwa kipi kinafaa insha kuhusu teknolojia?","wrong_answer":"Insha","correct_answer":"Simu"}'::jsonb, 'The child thinks the word "insha" or the date is the title.', 'The question "Kichwa kipi kinafaa insha kuhusu teknolojia?" with "Insha" among the options.', 'Read the finished writing and ask: what is it about in three words?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T10_INSHA_YA_MAELEZO.INSHA.M3_INS_HALAFU_T10', 'KISW.G3.KUANDI.T10_INSHA_YA_MAELEZO.INSHA', 'Joins every sentence with "na halafu", so the writing is one long sentence.', '{"question":"Ni lipi limeandikwa vizuri?","wrong_answer":"Tuliamka na halafu tukaoga na halafu tukaenda sokoni.","correct_answer":"Tuliamka asubuhi. Tulioga, kisha tukaenda sokoni."}'::jsonb, 'Spoken retelling joins events with na halafu; the child writes as he talks.', 'The question "Ni lipi limeandikwa vizuri?" with "Tuliamka na halafu tukaoga na halafu tukaenda sokoni." among the options.', 'Give a word bank: kwanza, kisha, baadaye, mwishowe; one per sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T10_INSHA_YA_MAELEZO.INSHA.M3_INS_TENSE_T10', 'KISW.G3.KUANDI.T10_INSHA_YA_MAELEZO.INSHA', 'Slips from one tense to another in the middle of the writing (past -li- to present -na-, or habitual hu- to past).', '{"question":"Ni lipi sahihi?","wrong_answer":"Simu hutumika kuwasiliana. Iliwasaidia watu kuzungumza.","correct_answer":"Simu hutumika kuwasiliana. Huwasaidia watu kuzungumza."}'::jsonb, 'The child thinks of the events as he writes and the tense of the moment comes in.', 'The question "Ni lipi sahihi?" with "Simu hutumika kuwasiliana. Iliwasaidia watu kuzungumza." among the options.', 'Underline every verb; all the tense markers should match.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.KUANDI.T10_INSHA_YA_MAELEZO.INSHA.M3_INS_MIX_T10', 'KISW.G3.KUANDI.T10_INSHA_YA_MAELEZO.INSHA', 'Puts English or Sheng words into the Kiswahili writing.', '{"question":"Sahihisha:","wrong_answer":"Simu ina screen na battery.","correct_answer":"Simu ina skrini na betri."}'::jsonb, 'The child does not know the Kiswahili word and fills the gap with the one he knows.', 'The question "Sahihisha:" with "Simu ina screen na battery." among the options.', 'Keep a word bank of theme words on the board before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME.M3_SAR_NEGATE_T10', 'KISW.G3.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME', 'Gives the negative of the verb (hafungui) instead of its opposite action (funga).', '{"question":"Kinyume cha \"washa\" (redio) ni?","wrong_answer":"usiwashe","correct_answer":"zima"}'::jsonb, 'The child thinks "opposite" means "not doing it".', 'The question "Kinyume cha "washa" (redio) ni?" with "usiwashe" among the options.', 'Act it: fungua the door, then funga it; not doing anything is not the opposite.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME.M3_SAR_ADDUA_T10', 'KISW.G3.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME', 'Makes an opposite by adding -ua to any verb (keti -> ketua).', '{"question":"Kinyume cha \"keti\" ni?","wrong_answer":"ketua","correct_answer":"simama"}'::jsonb, 'Fungua/funga and vaa/vua show a pattern, and the child uses it everywhere.', 'The question "Kinyume cha "keti" ni?" with "ketua" among the options.', 'Sort pairs into two piles: made with -ua (funga-fungua) and different words (keti-simama).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME.M3_SAR_SAME_T10', 'KISW.G3.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME', 'Gives a word of the same meaning as the opposite (simama - inuka).', '{"question":"Kinyume cha \"simama\" ni?","wrong_answer":"inuka","correct_answer":"keti"}'::jsonb, 'The child knows the words go together but not that they mean the same.', 'The question "Kinyume cha "simama" ni?" with "inuka" among the options.', 'Act both words: if the action is the same, it is not the opposite.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G3.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME.M3_SAR_NOUNOPP_T10', 'KISW.G3.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME', 'Gives a place or thing word as the opposite of an action (ingia - nje).', '{"question":"Kinyume cha \"ingia\" ni?","wrong_answer":"nje","correct_answer":"toka"}'::jsonb, 'Ingia and nje are heard together in "ingia ndani, toka nje".', 'The question "Kinyume cha "ingia" ni?" with "nje" among the options.', 'Ask "Ni kitendo?" before accepting: the opposite of an action is an action.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
